function displayCollection(key){const base=(state[key]||[]).filter(x=>key!=='papers'||!x.resolvedPaperId);if(key==='notes'||!catalogEntries.length)return base;const publicEntries=catalogEntries.filter(e=>!seedPaperIds.has(e.id)&&(e.id===catalogReadPaperId||!personalCatalogPaper(e.id))),ids=new Set(publicEntries.map(e=>e.id)),out=base.filter(x=>!ids.has(key==='papers'?x.id:x.paperId));for(const e of publicEntries){if(key==='papers')out.push({...e.paper,id:e.id,catalogPublished:true,catalogRevision:e.revision});else for(const item of (e[key]||[])){const old=base.find(x=>x.id===item.id);out.push({...item,paperId:e.id,...(key==='figures'?{saved:!!old?.saved}:{})});}}return out;}
