function write(entries){assertWritableWorkspace();return new Promise((ok,no)=>{const t=db.transaction('entries','readwrite');const s=t.objectStore('entries');entries.forEach(([k,v])=>s.put(v,k));t.oncomplete=ok;t.onerror=()=>no(t.error);t.onabort=()=>no(t.error||new Error('存储事务已取消'));});}
