async function importLegacyWorkspace(){
 if(!identity.authenticated||!identity.canImportLegacy)return false;
 const old=await new Promise((ok,no)=>{const request=indexedDB.open('chemlens-local');request.onupgradeneeded=()=>request.transaction.abort();request.onsuccess=()=>ok(request.result);request.onerror=()=>request.error?.name==='AbortError'?ok(null):no(request.error);});
 if(!old)return false;
 let entries;
 try{if(!old.objectStoreNames.contains('entries'))return false;entries=await new Promise((ok,no)=>{const tx=old.transaction('entries'),out=[],request=tx.objectStore('entries').openCursor();request.onsuccess=()=>{const cursor=request.result;if(!cursor)return;if(cursor.key==='state'||(typeof cursor.key==='string'&&cursor.key.startsWith('pdf:')))out.push([cursor.key,cursor.value]);cursor.continue();};tx.oncomplete=()=>ok(out);tx.onerror=()=>no(tx.error);});}finally{old.close();}
 const saved=entries.find(([key])=>key==='state')?.[1];if(!saved||typeof saved!=='object'||!Array.isArray(saved.papers))return false;
 const migrated=migrateState(saved);assertWritableWorkspace();
 return new Promise((ok,no)=>{const tx=db.transaction('entries','readwrite'),store=tx.objectStore('entries'),count=store.count();let imported=false;count.onsuccess=()=>{if(count.result!==0)return;store.put(migrated,'state');for(const [key,value] of entries)if(key!=='state')store.put(value,key);imported=true;};tx.oncomplete=()=>ok(imported);tx.onerror=()=>no(tx.error);tx.onabort=()=>no(tx.error||new Error('旧工作区迁移已取消'));});
}
