function tagChoicesMarkup(scoped){const pool=countTags(scoped);for(const tag of selectedFigureTags)if(!pool.some(x=>x.tag===tag))pool.push({tag,count:0});const choices=sortTagChoices(pool.filter(({tag})=>tagMatchesQuery(tag,tagQuery)),tagOrder,tagOrder==='pinyin'?tagLetter:'');return choices.length?choices.map(({tag,count})=>`<button type="button" class="tag-filter-chip ${selectedFigureTags.includes(tag)?'active':''}" data-action="filter-tag" data-tag="${esc(tag)}" aria-pressed="${selectedFigureTags.includes(tag)}" aria-label="${esc(tag)}，当前范围 ${count} 张图"><span>${esc(tag)}</span><span class="tag-filter-count">${count}</span></button>`).join(''):`<p class="helper">${tagQuery?'没有匹配的标签，可换一个同义词搜索。':'当前范围尚无画法标签；可打开图表，在“编辑解读”中添加。'}</p>`;}
function tagFilterPanel(scoped,resultCount){const active=selectedFigureTags.length||figurePaperFilter||figureJournalFilter||query||category!==categories[0]||methodFilter;return `<section class="tag-filter-panel" aria-label="图表画法标签筛选"><div class="tag-filter-header"><div><h3>${icon('grid',17)} 按画法找图</h3><p>一张图可有多个标签，跨论文寻找可借鉴的表现方式。</p></div><span class="tag-result-count">当前结果 <strong>${resultCount}</strong> 张</span></div><div class="tag-filter-controls"><label class="tag-control"><span>期刊</span><select class="select" id="figure-journal-filter" aria-label="按期刊筛选图表"><option value="">全部期刊</option>${figureJournalFacets(visible(state.figures).filter(f=>(view!=='saved'||f.saved)&&(view!=='popular'||ratingFor(f)===5)),visible(state.papers)).map(({journal,count})=>`<option value="${esc(journal)}" ${figureJournalFilter===journal?'selected':''}>${esc(journal)} (${count}张)</option>`).join('')}</select></label><label class="tag-control"><span>来源文献</span><select class="select" id="figure-paper-filter" aria-label="按来源文献筛选"><option value="">所有文献</option>${visible(state.papers).map(p=>`<option value="${esc(p.id)}" ${figurePaperFilter===p.id?'selected':''}>${esc(displayPaperTitle(p))}</option>`).join('')}</select></label><label class="tag-control"><span>查找画法标签</span><input class="input" type="search" id="tag-query" value="${esc(tagQuery)}" aria-label="搜索画法标签及同义词" placeholder="例如：能量图、结构图、流程图"></label><div class="tag-control"><span>多选匹配方式</span><div class="tag-match-modes" role="group" aria-label="标签组合方式"><button type="button" data-action="tag-match-mode" data-mode="any" class="${tagMatchMode==='any'?'active':''}" aria-pressed="${tagMatchMode==='any'}">任一标签</button><button type="button" data-action="tag-match-mode" data-mode="all" class="${tagMatchMode==='all'?'active':''}" aria-pressed="${tagMatchMode==='all'}">全部标签</button></div></div></div><div class="tag-sort-bar"><label><span>标签排列</span><select class="select" id="tag-order"><option value="count" ${tagOrder==='count'?'selected':''}>数量：从多到少</option><option value="pinyin" ${tagOrder==='pinyin'?'selected':''}>拼音首字母 A–Z</option></select></label>${tagOrder==='pinyin'?`<div class="tag-initials" role="group" aria-label="按拼音首字母筛选"><button class="${!tagLetter?'active':''}" data-action="tag-initial" data-letter="">全部</button>${'ABCDEFGHIJKLMNOPQRSTUVWXYZ#'.split('').map(l=>`<button class="${tagLetter===l?'active':''}" data-action="tag-initial" data-letter="${l}" ${countTags(scoped).some(x=>tagInitial(x.tag)===l)?'':'disabled'}>${l}</button>`).join('')}</div>`:''}</div><div class="tag-filter-chips" id="tag-choices">${tagChoicesMarkup(scoped)}</div><div class="tag-filter-summary"><div class="selected-tag-list">${selectedFigureTags.length?`<span>已选 ${selectedFigureTags.length} 个：</span>${selectedFigureTags.map(tag=>`<button type="button" class="selected-tag" data-action="filter-tag" data-tag="${esc(tag)}" aria-label="移除标签 ${esc(tag)}">${esc(tag)} <span aria-hidden="true">×</span></button>`).join('')}`:'<span>点击标签可多选</span>'}</div><button class="text-link" type="button" data-action="clear-tag-filters" ${!active?'disabled':''}>清空筛选</button></div><p class="tag-count-help">数字为当前期刊、文献、关键词、分类和方法范围内的图数；每张图在每个标签中只计一次。${selectedFigureTags.length>1&&tagMatchMode==='any'?'匹配标签更多的图优先显示，同匹配度内使用所选排序。':''}</p></section>`;}
function figureImage(f, p=paper(f.paperId)) {
 const image = f.image || '';
 return p?.releaseAccess?.figureImages === false && /^\/?assets\/papers\//.test(image) ? '' : image;
}
function sourceFigurePlaceholder(p) {
 const location = p?.releaseAccess?.originalPdf === false ? '原图见出版社' : '原图见原始 PDF';
 return `<div class="figure-source-placeholder">${icon('file',26)}<span>${location}</span></div>`;
}
function figureCard(f){const p=paper(f.paperId),image=figureImage(f,p);return `<article class="figure-card ${figureRatingTone(ratingFor(f)).highlight?'rated-highlight':''} ${ratingFor(f)===5?'five-star':''}" style="--rating-color:${figureRatingTone(ratingFor(f)).color}" data-figure-id="${esc(f.id)}"><div class="figure-visual"><button class="figure-open" data-action="figure" data-id="${f.id}" aria-label="查看图表：${esc(figureDisplayTitle(f))}">${image?`<img src="${esc(image)}" alt="${esc(figureDisplayTitle(f))}${f.demo?'，示意数据':''}" loading="lazy"><span class="figure-overlay">${icon('expand',18)} 放大查看</span>`:sourceFigurePlaceholder(p)}</button><span class="figure-number">${esc(f.number)}</span><button class="figure-copy icon-button" data-action="figure-copy" data-id="${esc(f.id)}" aria-label="复制图片：${esc(figureDisplayTitle(f))}" title="复制图片">${icon('copy',16)}</button><button class="figure-save ${f.saved?'saved':''}" data-action="save-figure" data-id="${f.id}" aria-label="${f.saved?'取消收藏':'收藏'}：${esc(figureDisplayTitle(f))}" aria-pressed="${!!f.saved}">${icon('save',17)}</button></div><div class="figure-content"><div class="card-top"><span class="category-pill">${esc(f.category)}</span><span class="card-method">${esc(f.method||'待记录方法')}</span></div><h2 class="figure-title"><button data-action="figure" data-id="${f.id}">${esc(figureDisplayTitle(f))}</button></h2><p class="figure-description">${scientificHTML(figureDescription(f,{caption:figureCaptionZh(f,p)}))}</p>${figureTagsHTML(f,true)}${ratingHTML(f,true)}<div class="figure-footer"><button class="paper-chip" data-action="paper" data-id="${f.paperId}" title="${esc(figurePaperSource(p))}">${icon('file',13)}<span>${esc(figurePaperSource(p))}</span></button><button class="figure-page" data-action="pdf" data-id="${f.paperId}" data-page="${f.page}">p. ${f.page} ${icon('arrow',13)}</button></div></div></article>`;}

function ratingFor(f){return figureStars(publicFigureRatings[f.id]?.rating??f.rating);}
function canRateFigure(f){return identity.authenticated;}
const ratingBusy=new Set();
async function refreshFigureRatings(){const revision=ratingsRevision;try{const data=await cloudFigureRatings();if(revision!==ratingsRevision)return;ratingsUnavailable=false;publicFigureRatings=data.ratings||{};const openId=modalKind==='figure'?$('#modal .dialog')?.dataset.figureId:null;render();if(openId)openFigure(openId);}catch{ratingsUnavailable=true;}}
async function rateFigure(id,rating){assertWritableWorkspace();const f=figure(id);if(!f||!Number.isInteger(rating)||rating<0||rating>5||ratingBusy.has(id))return;ratingBusy.add(id);try{if(isPublicFigure(f)){const result=await saveFigureRating({figureId:id,paperId:f.paperId,rating});ratingsRevision++;publicFigureRatings[id]=result;render();}else{const next=structuredClone(state),target=next.figures.find(x=>x.id===id);if(!target)throw Error('找不到这张个人图表。');target.rating=rating;await commit(next);}if(modalKind==='figure')openFigure(id);toast(isPublicFigure(f)?'评分已保存，已更新平均星级。':'已保存个人图表星级。');}finally{ratingBusy.delete(id);}}
function isPublicFigure(f){return seedFiguresById.has(f.id)||catalogEntries.some(e=>e.figures?.some(x=>x.id===f.id));}
function ratingHTML(f,compact=false){const value=ratingFor(f),editable=canRateFigure(f),entry=publicFigureRatings[f.id],count=entry?.count||0,myRating=isPublicFigure(f)?entry?.myRating:f.rating;return `<div class="figure-rating ${compact?'compact':''}" style="--rating-color:${figureRatingTone(value).color}" role="group" aria-label="图表星级"><span class="rating-label">${value===5?'五星精选':'星级'}</span><span class="rating-stars">${[1,2,3,4,5].map(n=>{const style=`--star-fill:${Math.max(0,Math.min(1,value-n+1))*100}%`;return editable?`<button type="button" class="rating-star" style="${style}" data-action="rate-figure" data-id="${esc(f.id)}" data-stars="${n}" aria-label="评为 ${n} 星" aria-pressed="${n===myRating}">★</button>`:`<span class="rating-star" style="${style}" aria-hidden="true">★</span>`;}).join('')}</span><span class="rating-value">${formatFigureStars(value)}/5${isPublicFigure(f)?` · ${count} 人`:''}</span>${editable?`<button type="button" class="text-link rating-clear" data-action="rate-figure" data-id="${esc(f.id)}" data-stars="0" aria-label="设为 0 星">0 星</button>`:isPublicFigure(f)?`<a class="text-link" href="${cloud.staticReader?'https://chemlens-yychu2020.chuyuyi1998.chatgpt.site/#gallery?figure='+encodeURIComponent(f.id):esc('/signin-with-chatgpt?'+new URLSearchParams({return_to:location.pathname+'#gallery?figure='+f.id}))}">${cloud.staticReader?'前往评分':'登录评分'}</a>`:''}</div>`;}

function paginationHTML(p){if(p.pages<=1)return '';const nums=[...new Set([1,...Array.from({length:5},(_,i)=>p.page+i-2).filter(n=>n>=1&&n<=p.pages),p.pages])].sort((a,b)=>a-b);return `<nav class="gallery-pagination" aria-label="图表分页"><span>第 ${p.start}–${p.end} 张 / 共 ${p.total} 张 · 每页最多 100 张</span><div><button class="button secondary" data-action="gallery-page" data-page="${p.page-1}" ${p.page===1?'disabled':''}>上一页</button>${nums.map((n,i)=>`${i&&n>nums[i-1]+1?'<span>…</span>':''}<button class="button ${n===p.page?'primary':'ghost'}" data-action="gallery-page" data-page="${n}" ${n===p.page?'aria-current="page"':''}>${n}</button>`).join('')}<button class="button secondary" data-action="gallery-page" data-page="${p.page+1}" ${p.page===p.pages?'disabled':''}>下一页</button></div></nav>`;}
async function openFigureLightbox(id){const f=figure(id),src=f&&figureImage(f,paper(f.paperId));if(!src)return;closeFigureLightbox({syncFigure:false});lightboxState={returnTo:document.activeElement,zoom:1,native:false,figureId:id};const host=document.createElement('section');host.id='figure-lightbox';host.className='figure-lightbox';host.setAttribute('role','dialog');host.setAttribute('aria-modal','true');host.setAttribute('aria-label','全屏查看图表');host.innerHTML=`<header><strong>${esc(figureDisplayTitle(f))}</strong><div class="action-row"><button class="button secondary" data-action="figure-previous" ${activeFigureNavigation(id).previous?'':'disabled'}>上一张</button><button class="button secondary" data-action="figure-next" ${activeFigureNavigation(id).next?'':'disabled'}>下一张</button><button class="icon-button" data-action="lightbox-out" aria-label="缩小全屏图片">${icon('minus')}</button><button class="button secondary" data-action="lightbox-reset" id="lightbox-zoom">适应屏幕</button><button class="icon-button" data-action="lightbox-in" aria-label="放大全屏图片">${icon('plus')}</button><button class="button primary" data-action="lightbox-close">返回图表</button></div></header><div class="lightbox-viewport" tabindex="0"><img id="lightbox-image" src="${esc(src)}" alt="${esc(figureDisplayTitle(f))}"></div>`;document.body.append(host);const im=$('#lightbox-image');im.onload=fitFigureLightbox;if(im.complete)fitFigureLightbox();host.querySelector('[data-action="lightbox-close"]').focus();try{if(host.requestFullscreen){await host.requestFullscreen();if(lightboxState)lightboxState.native=true;fitFigureLightbox();}}catch{} }
function fitFigureLightbox(){if(!lightboxState)return;const im=$('#lightbox-image'),viewport=$('.lightbox-viewport');if(!im?.naturalWidth||!viewport)return;const width=Math.max(100,viewport.clientWidth-40),height=Math.max(100,viewport.clientHeight-40),fit=Math.min(width/im.naturalWidth,height/im.naturalHeight);im.style.width=Math.round(im.naturalWidth*fit*lightboxState.zoom)+'px';$('#lightbox-zoom').textContent=lightboxState.zoom===1?'适应屏幕':Math.round(lightboxState.zoom*100)+'%';}
function closeFigureLightbox({syncFigure=true}={}){const previous=lightboxState;if(!previous)return;lightboxState=null;const host=$('#figure-lightbox');if(document.fullscreenElement===host)document.exitFullscreen?.().catch(()=>{});host?.remove();if(syncFigure&&modalKind==='figure'&&previous.figureId!==$('#modal .dialog')?.dataset.figureId){openFigure(previous.figureId);return;}if(previous.returnTo?.isConnected)previous.returnTo.focus();}
document.addEventListener('fullscreenchange',()=>{if(lightboxState?.native&&!document.fullscreenElement)closeFigureLightbox();});window.addEventListener('resize',fitFigureLightbox);

function orderedGalleryFigures(saved=false){const scoped=getScopedFigures(saved).filter(f=>view!=='popular'||ratingFor(f)===5);
 let figs=filterByTags(scoped,selectedFigureTags,tagMatchMode);
 if(sort==='title')figs.sort((a,b)=>a.title.localeCompare(b.title,'zh-CN'));
 if(sort==='recent'||sort==='default')figs=sortFiguresByPaperUpload(figs,state.papers);
 if(sort==='match'&&tagMatchMode==='any'&&selectedFigureTags.length>1)figs.sort((a,b)=>matchScore(b,selectedFigureTags)-matchScore(a,selectedFigureTags));
 if(sort==='stars-desc'||sort==='stars-asc'){figs=sortFiguresByStars(figs,ratingFor);if(sort==='stars-asc')figs.sort((a,b)=>ratingFor(a)-ratingFor(b));}
 return figs;
}
function galleryView(saved=false){
 const popular=view==='popular',scoped=getScopedFigures(saved).filter(f=>!popular||ratingFor(f)===5);
 const filterKey=JSON.stringify([view,query,category,methodFilter,sort,figurePaperFilter,figureJournalFilter,selectedFigureTags,tagMatchMode]);if(filterKey!==galleryFilterKey){galleryPage=1;galleryFilterKey=filterKey;}
 const figs=orderedGalleryFigures(saved);
 const paging=paginateFigures(figs,galleryPage);galleryPage=paging.page;
 return heading(popular?'受欢迎的图片':saved?'收藏图表':viewLabel('gallery'),popular?'五星精选，集中查看值得借鉴的图表。':saved?'把值得回看的图，留在触手可及的地方。':'收集图表、计算方法与研究思路。',`<div class="gallery-purpose"><h2>把论文读成研究思路</h2><p>查看原文，整理方法，记录灵感。</p></div>`)+(!saved&&!popular?`<div class="stats"><a class="stat stat-link" href="#papers" data-view="papers" aria-label="浏览已解读文献"><span class="stat-icon">${icon('book',21)}</span><span><strong class="stat-number">${visible(state.papers).filter(hasPaperAnalysis).length}<small> 篇</small></strong><span class="stat-label">已解读文献</span></span></a><a class="stat stat-link" href="#gallery?section=explore" data-view="gallery" data-section="explore" aria-label="跳转到图表探索区域"><span class="stat-icon">${icon('grid',21)}</span><span><strong class="stat-number">${visible(state.figures).length}<small> 张</small></strong><span class="stat-label">图表与机制</span></span></a>${identity.authenticated?`<a class="stat stat-link" href="#ideas" data-view="ideas" aria-label="浏览我的灵感"><span class="stat-icon">${icon('bulb',21)}</span><span><strong class="stat-number">${visible(state.notes).length}<small> 条</small></strong><span class="stat-label">我的灵感</span></span></a>`:`<a class="stat stat-link" href="#questions" data-view="questions"><span class="stat-icon">${icon('search',21)}</span><span><strong class="stat-number">${scientificQuestionPapers().length}<small> 项</small></strong><span class="stat-label">科学问题</span></span></a>`}</div>`:'')+`<div class="section-header" id="figure-explore" tabindex="-1" aria-label="探索图表">${identity.authenticated?'<button class="button secondary" data-action="removed-figures">已移除图表</button>':''}<h2 class="section-title">${popular?'五星图表':saved?'我的收藏':'探索图表'} <span>${figs.length}</span></h2><div class="filters"><label><span class="sr-only">按计算方法筛选</span><select class="select" id="method-filter"><option value="">全部方法</option>${['DFT','CI-NEB','AIMD'].map(t=>`<option ${methodFilter===t?'selected':''}>${t}</option>`).join('')}</select></label><label><span class="sr-only">图表排序</span><select class="select" id="sort-filter"><option value="default">最近上传论文</option>${selectedFigureTags.length>1?`<option value="match" ${sort==='match'?'selected':''}>标签匹配度</option>`:''}<option value="title" ${sort==='title'?'selected':''}>标题排序</option><option value="stars-desc" ${sort==='stars-desc'?'selected':''}>星级从高到低</option><option value="stars-asc" ${sort==='stars-asc'?'selected':''}>星级从低到高</option></select></label></div></div><div class="toolbar"><div class="category-tabs" role="group" aria-label="图表分类">${allCategories().map((c,i)=>`<button class="tab ${category===c?'active':''}" data-category="${c}" aria-pressed="${category===c}">${c}${i===0?` <span>${visible(state.figures).filter(f=>!saved||f.saved).length}</span>`:''}</button>`).join('')}</div></div>${tagFilterPanel(scoped,figs.length)}${paginationHTML(paging)}${figs.length?`<div class="gallery">${paging.items.map(figureCard).join('')}</div>${paginationHTML(paging)}`:empty(popular?'暂无五星图表':'当前组合没有匹配图表',popular?'注册用户评分后，平均星级达到5星的图表会在这里展示。':'可以切换为“任一标签”，或清空筛选后重新选择。',`<button class="button secondary" data-action="clear-tag-filters">清空筛选</button> <button class="button primary" data-action="upload">${icon('plus',16)} 上传论文</button>`)}<p class="footer-note">${cloud.online?'在线上传的PDF与AI解读保存云端；图表编辑与灵感保存在当前浏览器。':'本地导入的PDF、图表和笔记保存在当前浏览器。'}灵感支持 Markdown 导出。</p>`;
}
function paperStatus(p){if(p.catalogPublished)return privateLibrary()?'已保存资料':'公开文献';if(p.example||p.status==='已核对示例')return '原文已核对';return ({queued:'AI 排队中',processing:'AI 解读中',completed:'AI 草稿 · 待核对',pending:'待解读',failed:'AI 解读未完成'})[p.status]||p.status||'待解读';}
function displayPaperTitle(p){return paperDisplayName(paperTitles.apply(p||{}));}
function paperSource(p){return [p.journal,p.year,p.volume?(p.articleNumber?p.volume+':'+p.articleNumber:p.sourcePages?p.volume+', '+p.sourcePages:p.volume):p.articleNumber||'',p.doi?'DOI: '+p.doi:''].filter(Boolean).join(' · ')||p.sourceInfo||'来源信息待补充';}
function paperSearch(p){return matches(displayPaperTitle(p),p.shortTitle,p.title,p.englishTitle,p.authors?.join(' '),p.journal,p.year,p.doi,p.tags?.join(' '),getPaperTaxonomy(p).fields.join(' '),p.insight?.highlight,p.insight?.scientificQuestion);}
function paperTaxonomyHTML(p){const t=getPaperTaxonomy(p);return `<div class="paper-taxonomy-row" aria-label="所属文献分类"><button type="button" class="paper-taxonomy-chip" data-action="paper-taxonomy" data-dimension="year" data-value="${esc(t.year)}" title="打开${esc(t.year)}年份子列表">${esc(t.year)}</button><button type="button" class="paper-taxonomy-chip journal" data-action="paper-taxonomy" data-dimension="journal" data-value="${esc(t.journal)}" title="打开${esc(t.journal)}期刊子列表">${esc(t.journal)}</button>${t.fields.map(f=>`<button type="button" class="paper-taxonomy-chip field" data-action="paper-taxonomy" data-dimension="field" data-value="${esc(f)}" title="打开${esc(f)}研究领域子列表">${esc(f)}</button>`).join('')}</div>`;}
function editablePaperFields(p){if(!identity.authenticated)return '';const fields=normalizeResearchFields(p.researchFields);return `<section class="paper-field-editor"><span>文献标签</span><div class="figure-editable-tags">${fields.map(t=>`<span class="tag-chip">${esc(t)}<button data-action="paper-field-remove" data-id="${esc(p.id)}" data-tag="${esc(t)}" aria-label="删除文献标签 ${esc(t)}">×</button></span>`).join('')}</div><div class="figure-tag-add"><input class="input" id="paper-field-input" maxlength="800" aria-label="新增文献标签" placeholder="自由添加文献标签，多个用逗号分隔"><button class="button secondary" data-action="paper-field-add" data-id="${esc(p.id)}">添加</button></div></section>`;}
async function updatePaperFields(id,fields){const next=structuredClone(state),p=next.papers.find(x=>x.id===id);if(!p)throw Error('请重新打开文献。');p.researchFields=normalizeResearchFields(fields);p.taxonomyEdited=true;p.manualEdited=true;await commit(next);openPaper(id);toast('文献标签已保存');}
async function downloadPaperPDF(id){const p=paper(id);if(!p)return;const blob=await getPaperBlob(p);if(!blob)return toast('尚未保存 PDF，请先获取原文并入库。');download(blob,paperPDFDownloadName(paperTitles.apply(p)));}

function paperInsightHTML(p,compact=false){
 const i=p.insight||{},types=normalizeResearchFields(i.strengthTypes),pages=[...new Set((i.evidencePages||[]).filter(n=>Number.isInteger(n)&&n>=1&&n<=p.pages))];
 return `<section class="paper-insight ${compact?'paper-insight-mini':''}"><div class="insight-heading"><h3>这篇论文最牛的地方</h3></div>${types.length?`<div class="insight-types">${types.map(t=>`<span>${esc(t)}</span>`).join('')}</div>`:''}<p class="insight-highlight">${scientificHTML(i.highlight||'待研读：需要依据原文判断技术、构想或效率方面的突出贡献。')}</p>${!compact&&i.reasoning?`<p class="insight-reasoning">${scientificHTML(i.reasoning)}</p>`:''}<h4>科学问题</h4><p class="insight-scientific-question">${scientificHTML(i.scientificQuestion||'待梳理：结合原文提炼这篇论文解决的关键科学问题。')}</p>${!compact&&pages.length?`<div class="insight-evidence"><span>判断依据：</span>${pages.map(n=>`<button type="button" class="text-link" data-action="pdf" data-id="${p.id}" data-page="${n}">PDF 第 ${n} 页</button>`).join('')}</div>`:''}${!compact&&i.caveat?`<p class="insight-caveat">边界：${scientificHTML(i.caveat)}</p>`:''}</section>`;
}
function paperFilterOptions(options,value,label){const list=[...options];if(value&&!list.some(x=>x.value===value))list.push({value,count:0});return `<option value="">${label}</option>`+list.map(x=>`<option value="${esc(x.value)}" ${x.value===value?'selected':''}>${esc(x.value)}（${x.count} 篇）</option>`).join('');}
function paperFilterPanel(base,resultCount){const facets=buildPaperFacets(base,paperFilters),active=Object.values(paperFilters).some(Boolean)||paperPublicationFilter||paperOAFilter;return `<section class="library-filter-panel" aria-label="文献分类筛选"><div class="library-filter-header"><h3>按年份、期刊与研究领域浏览</h3><span>当前 <strong>${resultCount}</strong> 篇</span></div><div class="library-filter-controls"><label><span>发表年份</span><select class="select" id="paper-year-filter" aria-label="筛选发表年份">${paperFilterOptions(facets.years,paperFilters.year,'全部年份')}</select></label><label><span>发表期刊</span><select class="select" id="paper-journal-filter" aria-label="筛选发表期刊">${paperFilterOptions(facets.journals,paperFilters.journal,'全部期刊')}</select></label><label><span>研究领域</span><select class="select" id="paper-field-filter" aria-label="筛选研究领域">${paperFilterOptions(facets.fields,paperFilters.field,'全部研究领域')}</select></label><label><span>排序方式</span><select class="select" id="paper-date-sort">${Object.entries(PAPER_DATE_SORTS).map(([value,label])=>`<option value="${value}" ${paperDateSort===value?'selected':''}>${esc(label)}</option>`).join('')}</select></label><label><span>开放获取</span><select class="select" id="paper-oa-filter"><option value="">全部获取方式</option><option value="oa" ${paperOAFilter==='oa'?'selected':''}>OA 开放获取</option><option value="closed" ${paperOAFilter==='closed'?'selected':''}>非 OA</option><option value="unknown" ${paperOAFilter==='unknown'?'selected':''}>待查询</option></select></label>${identity.authenticated?`<label><span>公众号状态</span><select class="select" id="paper-publication-filter"><option value="">全部状态</option><option value="published" ${paperPublicationFilter==='published'?'selected':''}>已发公众号</option><option value="unpublished" ${paperPublicationFilter==='unpublished'?'selected':''}>尚未发表</option></select></label>`:''}</div><div class="library-filter-footer"><p>数量按关键词与另外两项筛选统计；一篇论文可同时进入多个研究领域。点击文献上的分类标签可打开对应子列表。</p><button type="button" class="text-link" data-action="paper-filters-clear" ${!active&&!query?'disabled':''}>清空筛选</button></div>${active?`<div class="library-filter-path">当前子列表：${[...Object.values(paperFilters),paperPublicationFilter?(paperPublicationFilter==='published'?'已发公众号':'尚未发表'):''].filter(Boolean).map(esc).join(' / ')}</div>`:''}</section>`;}
const preflightJobs=new Map();

async function ensurePreflight(id){if(preflightJobs.has(id))return preflightJobs.get(id);const job=(async()=>{const p=paper(id);if(!p||p.preflight)return p?.preflight;const blob=await getPaperBlob(p);if(!blob)return null;let doc;try{doc=await getPDF(new Uint8Array(await blob.arrayBuffer()));const result=await preprocessPDF(doc),next=structuredClone(state),target=next.papers.find(x=>x.id===id);if(!target)return null;if(target){target.preflight=result.preflight;target.pageTexts=result.texts;await commit(next);}if(modalKind==='paper'&&$('#modal .dialog')?.dataset.paperId===id)openPaper(id);return result.preflight;}catch(error){toast('文档自动准备未完成：'+error.message);return null;}finally{if(doc)await doc.loadingTask.destroy();}})();preflightJobs.set(id,job);try{return await job;}finally{preflightJobs.delete(id);}}
async function backfillPendingPreflights(){if(!identity.authenticated)return;for(const p of [...state.papers])if(!p.demo&&!p.example&&!p.summary&&!p.analysis&&!p.preflight&&!isPaperRemoved(p.id))await ensurePreflight(p.id);}
async function prepareForAI(p,file,onProgress=()=>{}){let doc;try{doc=await getPDF(new Uint8Array(await file.arrayBuffer()));const result=await preprocessPDF(doc,{onProgress}),analysisPacket=await buildAnalysisPacket(doc,result.preflight,{onProgress,forcePages:cloud.aiProvider==='zhipu',ops:pdfLib.OPS});result.preflight.mode=analysisPacket?'text-and-figure-pages':'original-pdf';const next=structuredClone(state),target=next.papers.find(x=>x.id===p.id);if(target){target.preflight=result.preflight;target.pageTexts=result.texts;await commit(next);}return {analysisPacket};}finally{if(doc)await doc.loadingTask.destroy();}}
const paperSyncJobs=new Map();
function paperUploadMetadata(p){return {url:p.url||'',preflight:p.preflight||null,palette:p.palette||null};}
function paperSyncHTML(p){if(seedPaperIds.has(p.id)||p.demo)return '';const synced=p.cloud&&p.syncState!=='uploading',busy=paperSyncJobs.has(p.id),label=synced?'已同步到私人云端，同一账号可跨电脑阅读PDF':busy?'正在同步私人云端':p.syncError||'仅保存在本机，点击同步到网站';return synced?`<span class="paper-sync-corner synced" title="${esc(label)}" aria-label="${esc(label)}">${icon('check',14)}</span>`:`<button class="paper-sync-corner local" data-action="sync-paper" data-id="${esc(p.id)}" title="${esc(label)}" aria-label="${esc(label)}" ${busy?'disabled':''}>${icon('upload',14)}</button>`;}
async function syncPaperToCloud(id,{manual=false,rejectDuplicates=false}={}){
 if(paperSyncJobs.has(id))return paperSyncJobs.get(id);
 const p=paper(id);if(!p||p.cloud||seedPaperIds.has(id)||!identity.authenticated)return p?.id;
 const job=(async()=>{try{
  if(!cloud.online||!cloud.storageEnabled)throw new Error('云端暂不可用，PDF 仍保存在本机。');
  if(!p.preflight)await ensurePreflight(id);
  const file=await getPaperBlob(p);if(!file)throw new Error('未找到本机原 PDF，请在最初上传的浏览器中刷新并同步。');
  if(file.size>cloud.maxUploadBytes||p.pages>100)throw new Error('云端同步支持最大 25 MB、100 页；请压缩或拆分后上传。');
  const requestId=p.requestId||p.id,next=structuredClone(state);next.papers.find(x=>x.id===id).requestId=requestId;await commit(next);
  const result=await uploadCloudPaper(file,{title:p.title,tags:p.tags||[],pageCount:p.pages,requestId,analyze:false,metadata:paperUploadMetadata(paper(id)||p)});
  if(result.paper.syncState==='uploading')throw new Error('PDF 正在同步，请稍后刷新或重试。');
  await mergeCloudDetail(result,{replaceLocalId:id,file});if(manual)toast('已同步到私人云端，其他电脑登录同一账号后刷新即可看到。');return result.paper.id;
 }catch(error){if(rejectDuplicates&&error.code==='DUPLICATE_PAPER')throw error;const next=structuredClone(state),target=next.papers.find(x=>x.id===id);if(target){target.syncError=error.message;await commit(next);}if(manual)toast(error.message);return null;}})();paperSyncJobs.set(id,job);try{return await job;}finally{paperSyncJobs.delete(id);render();}
}
function paperBibliographyHTML(p){return `${bibliography.badge(p)}<span class="paper-publication-date" title="${p.dateSource==='pdf'?'日期取自PDF原文':'来源索引日期，优先以PDF标注为准'}">${esc(bibliography.dateLabel(p))}</span>${identity.authenticated?`<button class="text-link" data-action="paper-bibliography" data-id="${esc(p.id)}">查询OA与日期</button>`:''}`;}
function paperCard(p){return `<article class="paper-card" data-paper-id="${esc(p.id)}"><div class="paper-details"><div class="paper-card-top"><span class="status-badge">${esc(paperStatus(p))}</span><button type="button" class="paper-remove-button" data-action="paper-remove" data-id="${p.id}">从库中移除</button></div><h2 class="paper-title"><button data-action="paper" data-id="${p.id}">${esc(displayPaperTitle(p))}</button></h2>${p.englishTitle?`<p class="paper-english-title">${esc(p.englishTitle)}</p>`:''}<p class="paper-source-line">${esc(paperSource(p))}</p>${paperTaxonomyHTML(p)}<div class="paper-bibliography">${paperBibliographyHTML(p)}</div>${paperSyncHTML(p)}${p.submissionStatus?`<span class="status-badge">个人上传 · ${{pending:'公共库待审核',approved:'已获准入公共库',rejected:'暂不准入公共库'}[p.submissionStatus]||'待审核'}</span>`:''}${paperInsightHTML(p,true)}<div class="tag-list">${(p.tags||[]).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>${renderPaperPalette(p,{compact:true})}${publicationTracker.render(p)}<div class="paper-card-footer"><p class="paper-meta">${visible(state.figures).filter(f=>f.paperId===p.id).length} 张图表 · ${p.pages} 页 · ${esc((p.createdAt||'').slice(0,10))}</p><div class="action-row"><button class="button primary" data-action="paper" data-id="${p.id}">${icon('spark',16)} 查看中文解读</button><button class="button secondary" data-action="pdf" data-id="${p.id}">${icon('book',17)} 阅读全文</button><button class="button secondary" data-action="paper-download" data-id="${esc(p.id)}">${icon('download',16)} 下载 PDF</button></div></div></div></article>`;}
function papersView(){
 const base=visible(state.papers).filter(hasPaperAnalysis).filter(paperSearch).map(p=>bibliography.apply(p)),papers=sortLibraryPapers(filterPapers(base,paperFilters).filter(p=>!paperPublicationFilter||publicationTracker.isPublished(p)===(paperPublicationFilter==='published')).filter(p=>!paperOAFilter||(paperOAFilter==='oa'?bibliography.apply(p).isOA===true:paperOAFilter==='closed'?bibliography.apply(p).isOA===false:bibliography.apply(p).isOA==null)),paperDateSort),removed=state.papers.filter(p=>!p.demo&&isPaperRemoved(p.id));
 return heading(viewLabel('papers'),'以科学问题和方法贡献组织论文，从来源与证据回到研究本身。',`${identity.authenticated?'<button class="button secondary" data-action="cloud-refresh">刷新云端</button>':''}<button class="button secondary" data-action="removed-papers">已移除文献${removed.length?' · '+removed.length:''}</button><button class="button primary" data-action="upload">${icon('upload',17)} 上传 PDF 并解读</button>`)+paperFilterPanel(base,papers.length)+`<div class="section-header"><h2 class="section-title">${Object.values(paperFilters).some(Boolean)||paperPublicationFilter||query?'筛选结果':'全部文献'} <span>${papers.length}</span></h2><span class="helper">分类标签可点击 · 研读判断与原文结论分别展示</span></div>`+(papers.length?`<div class="paper-grid">${papers.map(paperCard).join('')}</div>`:empty('当前分类中没有文献','可以调整下拉选项、清空关键词，或恢复已移除的文献。',`<button class="button secondary" data-action="paper-filters-clear">清空筛选</button><button class="button ghost" data-action="removed-papers">查看已移除文献</button>`))+`<p class="library-reading-note">“这篇论文最牛的地方”为研读判断，“科学问题”为文献研读概括，均非作者原话或官方评价。</p>`;
}
function pendingView(){const list=visible(state.papers).filter(isPendingPaper).filter(paperSearch);return heading('待解读文献','先保存论文，再补全中文解读、图表和方法。解读完成后会移入文献库。',`${identity.authenticated?'<button class="button secondary" data-action="deleted-tasks">已删除任务</button><button class="button secondary" data-action="cloud-refresh">刷新云端</button>':''}<button class="button primary" data-action="upload">${icon('upload',17)} 上传 PDF</button>`)+paperBatch.render()+(list.length?`${pendingBatchTools(list)}<div class="section-header"><h2 class="section-title">未完成解读 <span>${list.length}</span></h2></div><div class="paper-grid">${list.map(p=>`<article class="paper-card pending-paper-card" data-paper-id="${esc(p.id)}"><div class="paper-details">${cloud.aiEnabled?`<label class="pending-batch-choice"><input type="checkbox" data-pending-select="${esc(p.id)}" ${pendingSelection.has(p.id)?'checked':''} ${pendingEligible(p)?'':'disabled'}> 选择此篇</label>`:''}<span class="status-badge">${esc(paperStatus(p))}</span><h2 class="paper-title"><button data-action="paper" data-id="${p.id}">${esc(displayPaperTitle(p))}</button></h2><p class="paper-meta">${p.pages} 页 · ${esc((p.createdAt||'').slice(0,10))}</p><p class="pending-filename">${esc(p.filename||'PDF')}</p>${paperSyncHTML(p)}${p.submissionStatus?`<span class="status-badge">个人上传 · ${{pending:'公共库待审核',approved:'已获准入公共库',rejected:'暂不准入公共库'}[p.submissionStatus]||'待审核'}</span>`:''}${p.error?`<p class="hint">${esc(p.error.message||p.error)}</p>`:''}<div class="action-row"><button class="button primary" data-action="${p.pdfAvailable===false?'paper-pdf-restore':p.status==='queued'||p.status==='processing'||p.status==='failed'&&!canRetryAnalysis(p,{allowUnconfirmed:true})?'ai-refresh':'ai-start'}" data-id="${p.id}">${p.pdfAvailable===false?'补传原PDF':canRetryAnalysis(p,{allowUnconfirmed:true})?'恢复 AI 解读':p.status==='failed'?'刷新解读结果':p.status==='queued'||p.status==='processing'?'查看解读进度':'开始 AI 解读'}</button><button class="button secondary" data-action="pdf" data-id="${p.id}">阅读 PDF</button><button class="button ghost" data-action="paper" data-id="${p.id}">查看记录</button><button class="button task-delete-button" data-action="task-delete" data-id="${esc(p.id)}">删除任务</button></div></div></article>`).join('')}</div>`:empty('没有待解读的文献',query?'可清空搜索词查看全部待解读记录。':'新上传但尚未解读的 PDF 会出现在这里。',`<button class="button primary" data-action="upload">上传 PDF</button><a class="button secondary" href="#papers" data-view="papers">查看已解读文献</a>`));}
function usagePaginationHTML(p){const nums=[...new Set([1,...Array.from({length:5},(_,i)=>p.page+i-2).filter(n=>n>=1&&n<=p.pages),p.pages])].sort((a,b)=>a-b);return `<nav class="gallery-pagination usage-pagination" aria-label="Token 记录分页"><span>第 ${p.start}–${p.end} 条 / 共 ${p.total} 条 · 每页最多 30 条</span>${p.pages>1?`<div><button class="button secondary" data-action="tokens-page" data-page="${p.page-1}" ${p.page===1?'disabled':''}>上一页</button>${nums.map((n,i)=>`${i&&n>nums[i-1]+1?'<span>…</span>':''}<button class="button ${n===p.page?'primary':'ghost'}" data-action="tokens-page" data-page="${n}" ${n===p.page?'aria-current="page"':''}>${n}</button>`).join('')}<button class="button secondary" data-action="tokens-page" data-page="${p.page+1}" ${p.page===p.pages?'disabled':''}>下一页</button></div>`:''}</nav>`;}
function tokensView(){if(usageQuery!==query){usagePage=1;usageQuery=query;}const rows=usageHistory(state.papers,seed.papers,ownerUsageEvents).filter(r=>matches(r.paper.title,r.paper.filename,r.paper.journal,r.model,r.status)),totals=usageTotals(rows),pagination=paginateUsage(rows,usagePage),n=v=>Number(v).toLocaleString('zh-CN'),date=value=>{if(!value)return '未记录';const d=new Date(value);return Number.isNaN(d.getTime())?'未记录':new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);};usagePage=pagination.page;return heading('Token 消耗','历史上传、解读状态与实际 API 用量集中记录在这里。',`${identity.authenticated?'<button class="button secondary" data-action="cloud-refresh">刷新记录</button>':''}`)+`<div class="usage-summary"><section><span>累计实际用量</span><strong>${n(totals.total)}</strong><small>仅合计有 API 回执的记录</small></section><section><span>输入 / 输出</span><strong>${n(totals.input)} / ${n(totals.output)}</strong><small>包含接口返回的图像、指令等输入</small></section><section><span>历史记录</span><strong>${rows.length} 条</strong><small>${totals.measured} 条有实际用量，${totals.unrecorded} 条未记录实际用量</small></section></div>${usagePaginationHTML(pagination)}<div class="usage-table-wrap" id="usage-records"><table class="usage-table"><caption>历史上传与解读用量</caption><thead><tr><th>日期</th><th>文献</th><th>状态 / 来源</th><th>模型</th><th>实际输入</th><th>实际输出</th><th>实际合计</th><th>文字输入预估</th></tr></thead><tbody>${pagination.items.map(r=>`<tr data-usage-paper="${esc(r.id)}"><td>${esc(date(r.at))}</td><td>${r.paperId?`<a href="${esc(paperReadingHref(r.paperId,'tokens'))}" data-paper-route>${esc(displayPaperTitle(r.paper))}</a>`:`<span>${esc(displayPaperTitle(r.paper))}</span>`}<small>${esc(r.paper.filename||'')}</small>${isPaperRemoved(r.id)?'<small>文献已移除，保留历史</small>':''}</td><td>${esc(r.status)}<small>${r.origin}${r.paper.resolvedPaperId?' · 已关联库内解读':''}</small></td><td>${esc(r.paper.model||'未记录')}</td><td>${r.measured?n(r.usage.inputTokens):'—'}</td><td>${r.measured?n(r.usage.outputTokens):'—'}</td><td><strong>${r.measured?n(r.usage.totalTokens):'—'}</strong></td><td>${Number.isInteger(r.estimate)?n(r.estimate):'—'}</td></tr>`).join('')||'<tr><td colspan="8">暂无匹配的历史记录</td></tr>'}</tbody></table></div>${usagePaginationHTML(pagination)}<p class="usage-note">实际用量来自 API 返回的 usage；未记录不等于零消耗，未完成请求也可能产生费用。文字输入预估使用本地 o200k_base 计数，不含图像、指令、输出及推理，不计入实际合计。已关联的旧上传记录不会重复计算库内解读的用量。</p>`;}
function openTaskDeletion(id){const p=paper(id);if(!p||p.taskDeletedAt)return;modal('删除文献解读任务',`<h3>${scientificHTML(displayPaperTitle(p))}</h3><p>将此任务从待解读列表移除，并停止后续轮询和自动处理。</p><p class="helper">已上传的PDF和Token用量记录保留，可在“已删除任务”中恢复。已经发出的模型请求可能继续执行，删除任务不撤销已产生的费用。</p><div class="dialog-footer"><button class="button secondary" data-action="close">取消</button><button class="button task-delete-button" data-action="task-delete-confirm" data-id="${esc(id)}">确认删除任务</button></div>`,{kind:'task-delete'});}
async function confirmTaskDeletion(id){const revision=modalRevision,p=paper(id);if(!p)return;const button=$('[data-action="task-delete-confirm"]');if(button)button.disabled=true;try{const result=p.cloud?await deleteCloudPaperTask(id):{deletedAt:new Date().toISOString()};taskDeletionRevision++;if(cloudPolls.has(id)){clearTimeout(cloudPolls.get(id));cloudPolls.delete(id);}pendingSelection.delete(id);const next=structuredClone(state),target=next.papers.find(p=>p.id===id);if(target)target.taskDeletedAt=result.deletedAt;await commit(next);if(modalRevision===revision)closeModal({syncRoute:false});toast('任务已删除，PDF和用量记录保留');}catch(e){toast(e.message);if(button?.isConnected)button.disabled=false;}}
async function openDeletedTasks(){const local=state.papers.filter(p=>p.taskDeletedAt),items=new Map(local.map(p=>[p.id,{paper:p,deletedAt:p.taskDeletedAt}]));try{if(cloud.online&&identity.authenticated)for(const row of (await cloudDeletedTasks()).items||[])items.set(row.paper.id,row);}catch(e){toast(e.message);}const rows=[...items.values()].sort((a,b)=>b.deletedAt.localeCompare(a.deletedAt));modal('已删除任务',`<p class="helper">删除任务保留原PDF与用量记录。恢复只还原记录，不重新提交AI。</p>${rows.length?rows.map(({paper:p,deletedAt})=>`<article class="deleted-task-row"><div><h3>${scientificHTML(displayPaperTitle(p))}</h3><p class="helper">${esc(p.filename||'')} · 删除于 ${esc(new Date(deletedAt).toLocaleString())}</p></div><button class="button secondary" data-action="task-restore" data-id="${esc(p.id)}" data-cloud="${p.cloud||p.pdfUrl?.startsWith('/api/')?'true':'false'}">恢复任务</button></article>`).join(''):'<p class="helper">暂无已删除任务。</p>'}`,{wide:true,kind:'deleted-tasks'});}
async function restoreTask(id,isCloud){try{taskDeletionRevision++;if(isCloud){const d=await restoreCloudPaperTask(id);await mergeCloudDetail(d,{restoreDeletedTask:true});scheduleCloudPoll(id);}else{const next=structuredClone(state),p=next.papers.find(p=>p.id===id);if(p)p.taskDeletedAt='';await commit(next);}await openDeletedTasks();toast('任务已恢复，未重新提交AI');}catch(e){toast(e.message);}}
function openPaperRemoval(id){const p=paper(id);if(!p)return;const figures=state.figures.filter(f=>f.paperId===id).length,notes=state.notes.filter(n=>n.paperId===id).length;modal('从文献库中移除',`<div class="remove-paper-dialog"><h3>${scientificHTML(displayPaperTitle(p))}</h3><p>将从当前工作区隐藏这篇文献，以及关联的 ${figures} 张图表、计算方法和 ${notes} 条灵感笔记。</p><p class="hint">PDF、解读和个人笔记会保留，不会删除原始文件或云端对象。可通过“已移除文献”恢复；此操作保存在当前浏览器。</p></div><div class="dialog-footer"><button class="button secondary" data-action="paper" data-id="${id}">返回文献</button><button class="button danger" data-action="paper-remove-confirm" data-id="${id}">确认移除</button></div>`,{kind:'paper-removal'});}
function openRemovedPapers(){const removed=state.papers.filter(p=>!p.demo&&isPaperRemoved(p.id));modal('已移除文献',`<p class="helper">恢复后，原有图表、标签、计算方法和笔记会一并重新显示。未删除源 PDF。</p>${removed.length?`<div class="removed-paper-list">${removed.map(p=>`<article><div><h3>${scientificHTML(displayPaperTitle(p))}</h3><p>${esc(paperSource(p))}</p></div><button type="button" class="button secondary" data-action="paper-restore" data-id="${p.id}">恢复文献</button></article>`).join('')}</div>`:'<div class="empty-state"><h3>没有已移除文献</h3><p>文献卡片上的“从库中移除”可隐藏不需要的条目。</p></div>'}`,{wide:true,kind:'removed-papers'});}

function paperReadingHref(id,from='methods'){return '#papers?'+new URLSearchParams({paper:id,from}).toString();}
function methodSourceHTML(m){const p=paper(m.paperId),available=p&&!p.demo&&!isPaperRemoved(p.id),page=Number(m.page),validPage=available&&Number.isInteger(page)&&page>=1&&page<=Number(p.pages);return `<div class="method-source">${available?`<a class="method-paper-link" href="${esc(paperReadingHref(p.id))}" data-paper-route title="打开论文解读：${esc(displayPaperTitle(p))}">${icon('file',14)}<span>${esc(p.title||'中文题名待核实')}</span>${icon('arrow',14)}</a>`:`<span class="method-source-unavailable">${m.paperId?'关联文献不可用，可编辑后重新选择':'尚未关联文献'}</span>`}${validPage?`<button class="text-link method-source-page" data-action="pdf" data-id="${esc(p.id)}" data-page="${page}">定位 PDF 第 ${page} 页 ${icon('arrow',13)}</button>`:`<span class="method-source-page helper">${available?'原文页码待核实':'来源恢复后可定位原文'}</span>`}</div>`;}
function methodsView(){const all=visible(state.methods).filter(m=>matches(m.title,m.parameters,paper(m.paperId)?.title)),methods=all.filter(m=>!methodCategory||getMethodCategories(m).includes(methodCategory)),filters=`<div class="method-category-filter" aria-label="计算方法分类"><button class="tab ${!methodCategory?'active':''}" data-action="method-category" data-category="" aria-pressed="${!methodCategory}">全部方法 <span>${all.length}</span></button>${methodCategoryCounts(all).map(({category,count})=>`<button class="tab ${methodCategory===category?'active':''}" data-action="method-category" data-category="${esc(category)}" aria-pressed="${methodCategory===category}">${esc(category)} <span>${count}</span></button>`).join('')}</div>`;return heading('计算方法','把论文中的技术路线，整理成下一次计算的起点。',`<button class="button primary" data-action="method-new">${icon('plus',17)} 记录方法</button>`)+`<div class="panel"><div class="panel-header"><h2 class="section-title">一条可追溯的计算路线</h2><span class="demo-badge">记录框架 · 非论文参数</span></div><div class="method-steps">${workflow.map((s,i)=>`<div class="method-step"><span class="step-number">0${i+1}</span><h3>${s.title}</h3><p>${s.caption}</p><small>${s.details}</small></div>`).join('')}</div></div>${filters}<div class="section-header"><h2 class="section-title">我的方法记录 <span>${methods.length}</span></h2><span class="helper">参数、原文页码与待核实项一并保存</span></div>${methods.length?`<div class="method-grid">${methods.map(m=>`<article class="method-card" data-method-id="${esc(m.id)}"><div class="card-top"><span class="category-pill">${esc(m.software||'计算方法')}</span>${icon('flask')}</div><div class="method-category-tags">${getMethodCategories(m).map(c=>`<span class="category-pill">${esc(c)}</span>`).join('')}</div><h3>${esc(m.title)}</h3><p class="note-text">${scientificHTML(m.parameters)}</p>${methodSourceHTML(m)}<button class="button secondary" data-action="method-edit" data-id="${m.id}">${icon('edit',15)} 编辑方法记录</button></article>`).join('')}</div>`:empty('把一套方法，变成可复用的记录','记录软件、泛函、赝势、收敛条件及证据位置。原文缺失的参数请保留为“待核实”。',`<button class="button secondary" data-action="method-new">${icon('plus',16)} 新建方法记录</button>`)}`;}
const CATALOG_MIB=1024*1024;
function assertCatalogAdmin(){assertWritableWorkspace();if(privateLibrary())throw new Error('私人文献库模式不提供对外发布或撤回操作。');if(!identity.isCatalogAdmin)throw new Error('此操作仅对公开文献库管理员开放。');}
async function catalogRequest(path='',options={}){const response=await fetch('/api/catalog'+path,{credentials:'same-origin',...options});let data;try{data=await response.json();}catch{throw new Error('公开文献服务暂不可用，请稍后重试。');}if(!response.ok){const error=new Error(data.error?.message||'公开文献操作未完成。');error.status=response.status;throw error;}return data;}
async function loadCatalog({notify=false}={}){if(catalogLoading)return;catalogLoading=true;catalogError='';try{let cursor='',entries=[],seen=new Set();for(let page=0;page<30;page++){const data=await catalogRequest(cursor?'?cursor='+encodeURIComponent(cursor):'');for(const e of data.entries||[])if(e&&typeof e.id==='string'&&e.paper&&Array.isArray(e.figures)&&Array.isArray(e.methods))entries.push(e);const next=data.nextCursor;if(!next||seen.has(next))break;seen.add(next);cursor=next;}catalogEntries=[...new Map(entries.map(e=>[e.id,e])).values()];render();if(modalKind==='paper'&&$('#modal .dialog')?.dataset.paperId)openPaper($('#modal .dialog').dataset.paperId);else if(modalKind==='paper-unavailable'&&activePaperRoute?.paperId&&catalogEntries.some(e=>e.id===activePaperRoute.paperId))openPaper(activePaperRoute.paperId);if(notify)toast(privateLibrary()?'私人资料已同步':'公开文献库已刷新');}catch(error){catalogError=error.message;if(notify)toast(catalogError);}finally{catalogLoading=false;if(view==='admin')renderContent();}}
function adminPapers(){const rows=state.papers.filter(p=>!p.demo&&!isPaperRemoved(p.id)&&(!seedPaperIds.has(p.id)||catalogEntries.some(e=>e.id===p.id)));for(const e of catalogEntries)if(!isPaperRemoved(e.id)&&!rows.some(p=>p.id===e.id))rows.push(e.paper);return rows;}
function privateAdminView(){const papers=visible(state.papers);if(!papers.some(p=>p.id===adminPaperId))adminPaperId=papers[0]?.id||'';const selected=papers.find(p=>p.id===adminPaperId);return heading('资料管理','导入和整理本人的论文、图表与研读记录。',`<button class="button secondary" data-action="catalog-refresh">同步已有资料</button><button class="button primary" data-action="catalog-import">${icon('upload',16)} 导入 PDF</button>`)+`<section class="catalog-draft panel"><h2 class="section-title">个人文献</h2><label class="field"><span>选择要整理的文献</span><select class="select" id="catalog-paper-select">${papers.map(p=>`<option value="${esc(p.id)}" ${p.id===adminPaperId?'selected':''}>${esc(displayPaperTitle(p))}</option>`).join('')}</select></label>${selected?`<p class="helper">${esc(paperSource(selected))} · ${selected.pages} 页</p><div class="action-row"><button class="button secondary" data-action="catalog-open" data-id="${esc(selected.id)}">查看解读、图表与方法</button><button class="button secondary" data-action="catalog-edit" data-id="${esc(selected.id)}">编辑中文解读与科学问题</button></div>`:''}<p class="hint private-library-note">当前为仅本人访问的私人文献库，可继续上传、编辑、收藏和阅读资料。</p></section><section class="catalog-published"><div class="section-header"><h2 class="section-title">已有资料记录 <span>${catalogEntries.length}</span></h2></div>${catalogError?`<p class="hint">${esc(catalogError)}</p>`:''}${catalogEntries.length?`<div class="catalog-entry-list">${catalogEntries.map(e=>`<article class="catalog-entry" data-catalog-id="${esc(e.id)}"><div><h3>${esc(displayPaperTitle(e.paper))}</h3><p>${e.figures.length} 张图表 · ${e.methods.length} 条方法 · ${esc((e.updatedAt||'').replace('T',' ').slice(0,16))}</p></div><a class="button secondary" href="${esc(paperReadingHref(e.id,'admin')+'&source=catalog')}" data-paper-route>阅读已保存资料</a></article>`).join('')}</div>`:'<p class="helper">原有上传、笔记和收藏继续保存在个人工作区。</p>'}</section>`;}
function adminView(){if(privateLibrary())return privateAdminView();const papers=adminPapers();if(!papers.some(p=>p.id===adminPaperId))adminPaperId=papers[0]?.id||'';const selected=papers.find(p=>p.id===adminPaperId),published=catalogEntries.find(e=>e.id===adminPaperId);return heading('管理员工作台','在个人工作区整理内容，审阅后选择公开发布。',`<button class="button secondary" data-action="catalog-refresh">刷新公开目录</button><button class="button primary" data-action="catalog-import">${icon('upload',16)} 导入新 PDF</button>`)+submissionPanel()+`<section class="catalog-draft panel"><h2 class="section-title">选择站内上传的个人文献</h2><label class="field"><span>个人上传与已发布条目</span><select class="select" id="catalog-paper-select" ${catalogBusy?'disabled':''}>${papers.length?papers.map(p=>`<option value="${esc(p.id)}" ${p.id===adminPaperId?'selected':''}>${esc(displayPaperTitle(p))}</option>`).join(''):'<option value="">请先导入 PDF</option>'}</select></label>${selected?`<p class="helper">${esc(paperSource(selected))} · ${selected.pages} 页${published?' · 已公开版本 '+esc(published.revision):' · 尚未公开'}</p><div class="action-row"><button class="button secondary" data-action="catalog-open" data-id="${esc(selected.id)}">查看解读、图表与方法</button><button class="button secondary" data-action="catalog-edit" data-id="${esc(selected.id)}">编辑中文解读与科学问题</button><button class="button primary" data-action="catalog-review" data-id="${esc(selected.id)}" ${catalogBusy?'disabled':''}>${published?'审阅并更新公开版本':'审阅后发布'}</button></div>`:''}<p class="catalog-progress" id="catalog-progress" role="status"></p><p class="hint">可选择站内导入的个人 PDF，或更新已经公开的条目。预置文献通过站点构建发布。个人灵感笔记、收藏与账号信息不会发布。</p></section><section class="catalog-published"><div class="section-header"><h2 class="section-title">已发布到公开文献库 <span>${catalogEntries.length}</span></h2></div>${catalogError?`<p class="hint">${esc(catalogError)}</p>`:''}${catalogEntries.length?`<div class="catalog-entry-list">${catalogEntries.map(e=>`<article class="catalog-entry" data-catalog-id="${esc(e.id)}"><div><h3>${esc(displayPaperTitle(e.paper))}</h3><p>${e.figures.length} 张图表 · ${e.methods.length} 条方法 · 版本 ${esc(e.revision)} · ${esc((e.updatedAt||'').replace('T',' ').slice(0,16))}</p></div><div class="action-row"><a class="button secondary" href="${esc(paperReadingHref(e.id,'admin')+'&source=catalog')}" data-paper-route>阅读公开内容</a>${papers.some(p=>p.id===e.id)?`<button class="button secondary" data-action="catalog-review" data-id="${esc(e.id)}" ${catalogBusy?'disabled':''}>审阅更新</button>`:''}<button class="button ghost" data-action="catalog-withdraw" data-id="${esc(e.id)}" ${catalogBusy?'disabled':''}>撤回公开</button></div></article>`).join('')}</div>`:'<p class="helper">尚未通过工作台公开发布文献。</p>'}</section>`;}
function pickCatalogFields(value,keys){const out={};for(const key of keys)if(value&&value[key]!==undefined)out[key]=structuredClone(value[key]);return out;}
function catalogSnapshot(p,figures,methods){const item=pickCatalogFields(p,['id','title','chineseTitle','englishTitle','shortTitle','short','authors','journal','year','volume','articleNumber','sourcePages','doi','url','publisherUrl','citation','pages','filename','tags','researchFields','status','createdAt','license','licenseUrl','insight','scientificAnswer','summary','keyFindings','novelty','limitations','palette']);const analysis=p.analysis?.summary;if(analysis)item.analysis={summary:pickCatalogFields(analysis,['researchQuestion','mainFindings','novelty','limitations'])};return {paper:item,figures:figures.map(f=>pickCatalogFields(f,['id','paperId','title','number','page','image','category','method','description','question','reading','finding','limits','tags','caption','captionZh','captionEdited','aiGenerated','manualEdited','sourcePreview','cropNeedsReview'])),methods:methods.map(m=>pickCatalogFields(m,['id','paperId','title','software','page','parameters','evidence','aiGenerated','manualEdited']))};}
function catalogProgress(text){const el=$('#catalog-review-status')||$('#catalog-withdraw-status')||$('#catalog-progress');if(el)el.textContent=text;}
async function figurePublicationBlob(f){const source=f.image;if(!source||/favicon\.svg(?:$|\?)/.test(source))return null;if(!source.startsWith('data:')&&!source.startsWith('blob:')&&new URL(source,location.href).origin!==location.origin)throw new Error(`${f.number||f.title} 的图像需先保存到本站。`);const response=await fetch(source,{credentials:'same-origin'});if(!response.ok)throw new Error(`${f.number||f.title} 图像读取失败，请重新收集。`);const blob=await response.blob();if(!/^image\/(png|jpeg|webp)$/i.test(blob.type))throw new Error(`${f.number||f.title} 需使用 PNG、JPEG 或 WebP 图像。`);return blob;}
async function fitPublicationImage(blob,maxBytes){const image=await createImageBitmap(blob);try{if(blob.size<=maxBytes&&image.width<=12000&&image.height<=12000&&image.width*image.height<=24000000)return {blob,optimized:false};let edge=Math.min(2400,Math.max(image.width,image.height));for(let round=0;round<7;round++){const scale=Math.min(1,edge/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);for(const quality of [.92,.84,.74]){const out=await new Promise(ok=>canvas.toBlob(ok,'image/jpeg',quality));if(out&&out.size<=maxBytes)return {blob:out,optimized:true};}edge*=.75;}throw new Error('图像仍超过公开上传限制，请缩小图像后重新收集。');}finally{image.close();}}
function publicationDataURL(blob){return new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=()=>no(r.error);r.readAsDataURL(blob);});}
async function prepareCatalogReview(id,source=null){assertCatalogAdmin();if(catalogBusy)return;catalogBusy=true;pendingPublication=null;try{if(!source&&seedPaperIds.has(id)&&!catalogEntries.some(e=>e.id===id))throw new Error('预置文献通过站点构建发布，请先导入个人 PDF。');catalogProgress('正在准备公开内容…');if(!source)await ensurePersonalPaper(id);const p=source?.paper||state.papers.find(p=>p.id===id);if(!p||isPaperRemoved(id))throw new Error('请先选择个人工作区中的文献。');const figures=source?.figures||state.figures.filter(f=>f.paperId===id&&!f.demo),methods=source?.methods||state.methods.filter(m=>m.paperId===id&&!m.demo);if(figures.length>40||methods.length>40||p.pages>100)throw new Error('公开条目支持最多 100 页、40 张图和 40 条方法。');const file=source?.file||await getPaperBlob(p);if(!file)throw new Error('找不到原始 PDF，请先在个人工作区重新导入。');if(file.size>25*CATALOG_MIB)throw new Error('公开 PDF 最大 25 MiB，请压缩或拆分后导入。');const snapshot=catalogSnapshot(p,figures,methods),images=[];let optimized=0;for(let i=0;i<figures.length;i++){catalogProgress(`正在准备图像 ${i+1} / ${figures.length}…`);const source=await figurePublicationBlob(figures[i]);if(!source){images.push(null);continue;}const fitted=await fitPublicationImage(source,3*CATALOG_MIB);images.push(fitted.blob);if(fitted.optimized)optimized++;}if(images.reduce((n,b)=>n+(b?.size||0),0)>5*CATALOG_MIB){const budget=Math.floor((5*CATALOG_MIB-65536)/images.filter(Boolean).length);for(let i=0;i<images.length;i++){if(!images[i])continue;const fitted=await fitPublicationImage(images[i],budget);images[i]=fitted.blob;if(fitted.optimized)optimized++;}}for(let i=0;i<images.length;i++){if(images[i])snapshot.figures[i].image=await publicationDataURL(images[i]);else delete snapshot.figures[i].image;}const published=catalogEntries.find(e=>e.id===id);if(published)snapshot.expectedRevision=published.revision;const json=JSON.stringify(snapshot);if(new Blob([json]).size>8*CATALOG_MIB)throw new Error('解读与图像数据超过 8 MiB，请减少图表后重新审阅。');pendingPublication={id,snapshot,json,file,optimized,submission:source?.submission};openCatalogReview();}catch(error){catalogProgress(error.message);toast(error.message);}finally{catalogBusy=false;if(view==='admin')renderContent();}}
function openCatalogReview(){const ready=pendingPublication;if(!ready)return;const {snapshot:s,file}=ready,p=s.paper;modal('发布前审阅',`<div class="catalog-review"><p class="hint">点击发布后，访客和其他注册者均可阅读以下 PDF、图表与解读。个人灵感笔记不会加入公开内容。</p><h3>${scientificHTML(displayPaperTitle(p))}</h3><p class="paper-source-line">${esc(paperSource(p))}</p><p class="helper">原始 PDF：${esc(p.filename||'论文.pdf')} · ${(file.size/CATALOG_MIB).toFixed(1)} MiB · ${p.pages} 页；${s.figures.length} 张图，${s.methods.length} 条方法${s.expectedRevision?'；将更新版本 '+esc(s.expectedRevision):'；首次公开'}。</p>${ready.optimized?'<p class="helper">部分公开图像副本已优化尺寸与编码。</p>':''}${paperInsightHTML(p)}${p.scientificAnswer?`<section class="catalog-review-answer"><h3>论文对科学问题的回答</h3><p>${esc(p.scientificAnswer)}</p></section>`:''}${analysisSummaryHTML(p)}${ready.submission?`<a class="button secondary" href="/api/admin/submissions/${esc(ready.submission.id)}/pdf" target="_blank" rel="noopener noreferrer">查看投稿原 PDF</a>`:''}<h3 class="section-title">公开图表与中文解读</h3>${s.figures.length?s.figures.map(f=>`<details class="catalog-review-figure"><summary>${esc(f.number)} · ${esc(figureDisplayTitle(f))} · PDF 第 ${f.page} 页</summary>${f.image?`<img src="${esc(f.image)}" alt="${esc(figureDisplayTitle(f))}">`:'<p class="helper">本条仅公开图表解读，原图可在 PDF 中查看。</p>'}${f.captionZh?`<p>${esc(f.captionZh)}</p>`:''}${detailSection('这张图回答什么',f.question)}${detailSection('阅读方式',f.reading)}${detailSection('关键观察',f.finding)}${detailSection('适用边界',f.limits)}</details>`).join(''):'<p class="helper">没有图表，将公开 PDF 与已有研读内容。</p>'}<h3 class="section-title">公开计算方法</h3>${s.methods.map(m=>`<details class="catalog-review-method"><summary>${esc(m.title)}${m.page?' · PDF 第 '+m.page+' 页':''}</summary><p>${esc(m.parameters||'')}</p>${m.evidence?`<p>${esc(m.evidence)}</p>`:''}</details>`).join('')}<p id="catalog-review-status" class="catalog-progress" role="status"></p><div class="dialog-footer"><button class="button secondary" data-action="close">返回继续编辑</button><button class="button primary" data-action="catalog-publish">${s.expectedRevision?'更新到公开文献库':'发布到公开文献库'}</button></div></div>`,{wide:true,kind:'catalog-review'});}
async function publishCatalogReview(){assertCatalogAdmin();if(catalogBusy||!pendingPublication)return;const ready=pendingPublication;catalogBusy=true;const button=$('[data-action="catalog-publish"]');if(button)button.disabled=true;catalogProgress('正在发布 PDF、图像与解读…');try{const form=new FormData();form.append('snapshot',ready.json);form.append('file',ready.file,ready.snapshot.paper.filename||'paper.pdf');const data=ready.submission?await submissionRequest('/'+ready.submission.id+'/approve',{method:'POST',headers:{'X-Source-Revision':ready.submission.sourceUpdatedAt},body:form}):await catalogRequest('',{method:'POST',body:form});if(!data.published||!data.entry)throw new Error('服务未确认发布成功，请刷新目录核对。');catalogEntries=[...catalogEntries.filter(e=>e.id!==data.entry.id),data.entry];if(ready.submission)await loadSubmissions();pendingPublication=null;if(modalKind==='catalog-review')closeModal();render();toast(data.unchanged?'公开内容已是当前版本':'已发布到公开文献库');}catch(error){catalogProgress(error.message);if(error.status===409){pendingPublication=null;await loadCatalog();}toast(error.message);}finally{catalogBusy=false;if(view==='admin')renderContent();if(button?.isConnected)button.disabled=!pendingPublication;}}
function openCatalogWithdrawal(id){assertCatalogAdmin();const e=catalogEntries.find(x=>x.id===id);if(!e)return;modal('撤回公开内容',`<h3>${esc(displayPaperTitle(e.paper))}</h3><p class="helper">将撤回版本 ${esc(e.revision)} 的公开 PDF、图表和解读。个人工作区中的原记录与笔记会保留。${seedPaperIds.has(id)?'此文献另有站点预置来源卡，撤回只取消本次公开副本。':''}</p><div class="dialog-footer"><button class="button secondary" data-action="close">取消</button><button class="button danger" data-action="catalog-withdraw-confirm" data-id="${esc(id)}">确认撤回公开</button></div>`,{kind:'catalog-withdraw'});}
async function withdrawCatalogEntry(id){assertCatalogAdmin();if(catalogBusy)return;catalogBusy=true;try{const revision=catalogEntries.find(e=>e.id===id)?.revision;await catalogRequest('/'+encodeURIComponent(id),{method:'DELETE',headers:revision?{'If-Match':revision}:{}});catalogEntries=catalogEntries.filter(e=>e.id!==id);closeModal();render();toast('已撤回公开内容，个人工作区保留');}catch(error){toast(error.message);}finally{catalogBusy=false;if(view==='admin')renderContent();}}

function scientificQuestionPapers(){return visible(state.papers).filter(p=>typeof p.insight?.scientificQuestion==='string'&&p.insight.scientificQuestion.trim()&&!/^待(?:研读|梳理|核实)/.test(p.insight.scientificQuestion.trim()));}
function scientificAnswerHTML(p){const answer=typeof p.scientificAnswer==='string'?p.scientificAnswer.trim():'',highlight=typeof p.insight?.highlight==='string'?p.insight.highlight.trim():'';const text=answer||(!/^待(?:研读|梳理|核实)/.test(highlight)?highlight:'');return text?`<div class="question-answer"><h3>${answer?'论文回答':'相关贡献'}</h3><p>${esc(text)}</p></div>`:'';}
let questionStudyType='',methodCategory='';
