function figureQAPanel(f){const available=identity.authenticated&&cloud.aiEnabled&&cloud.aiProvider==='zhipu';let body;if(cloud.staticReader)body=`<p>在AI工作台登录后，可围绕这张图提问。</p><a class="button secondary" href="https://chemlens-yychu2020.chuyuyi1998.chatgpt.site/#gallery?figure=${encodeURIComponent(f.id)}" target="_blank" rel="noopener noreferrer">打开这张图的AI问答</a>`;else if(!identity.authenticated)body=`<p>登录管理员账号后使用已配置的AI问答。</p><a class="button secondary" href="${esc('/signin-with-chatgpt?'+new URLSearchParams({return_to:location.pathname+'#gallery?figure='+f.id}))}">登录并提问</a>`;else if(!available)body='<p>图片问答沿用付费AI权限，仅管理员可用。服务未启用时可先阅读现有解析。</p>';else body=`<form id="figure-qa-form"><label for="figure-qa-question">关于这张图，你想了解什么？</label><textarea id="figure-qa-question" name="question" rows="3" maxlength="2000" required placeholder="例如：这张图如何支持作者的结论？能怎样借鉴它的画法？"></textarea><div class="qa-actions"><button type="submit" class="button primary" id="figure-qa-submit">${icon('spark',15)} 询问AI</button><button type="button" class="button ghost" data-action="figure-qa-clear">清空</button></div></form><p id="figure-qa-status" class="qa-status" role="status"></p><div id="figure-qa-answer" class="qa-answer" role="region" aria-label="AI对当前图表的回答" hidden></div>`;return `<section class="figure-qa" aria-labelledby="figure-qa-heading"><h3 id="figure-qa-heading">${icon('spark',18)} 当前图片问答</h3><p class="qa-privacy">仅发送当前图片、对应解析和本次问题；本网站不保存问答内容。切图或关闭后清空。</p>${body}</section>`;}
function renderFigureQA(){const q=figureQA;if(!q||$('#modal .dialog')?.dataset.figureId!==q.figureId)return;const input=$('#figure-qa-question'),answer=$('#figure-qa-answer'),status=$('#figure-qa-status'),button=$('#figure-qa-submit');if(input&&input.value!==q.question)input.value=q.question;if(button){button.disabled=q.loading;button.textContent=q.loading?'正在回答…':'询问AI';}if(status){status.textContent=q.error||(q.loading?'正在查看当前图片并回答…':'');status.classList.toggle('has-error',!!q.error);}if(answer){answer.hidden=!q.answer;answer.textContent=q.answer;}}
