const originalCaptionJobs=new Map();
async function loadOriginalFigureCaption(id){const f=figure(id),p=f&&paper(f.paperId);if(!p||p.releaseAccess?.originalPdf===false)return;if(!originalCaptionJobs.has(id))originalCaptionJobs.set(id,(async()=>{let doc;try{const blob=await getPaperBlob(p);if(!blob)return '';doc=await getPDF(new Uint8Array(await blob.arrayBuffer()));for(const n of [...new Set([f.page,f.page+1,f.page-1])].filter(n=>n>=1&&n<=doc.numPages)){const page=await doc.getPage(n),caption=originalCaptionFromPage(await page.getTextContent(),page.getViewport({scale:1}),f.number);if(caption)return caption;}return '';}catch{return '';}finally{await doc?.loadingTask.destroy();}})());const caption=await originalCaptionJobs.get(id);if(!caption)return;const local=state.figures.find(x=>x.id===id);if(local)local.captionOriginal=caption;if($('#modal .dialog')?.dataset.figureId===id){const host=$('#figure-original-caption');if(host){host.querySelector('p').innerHTML=scientificHTML(caption);host.hidden=false;}}}
