function safeURL(value){if(!value.trim())return '';const u=new URL(value);if(!['http:','https:'].includes(u.protocol))throw new Error('原文链接须使用 http 或 https 地址。');return u.href;}
const COMMON_RESEARCH_FIELDS=['表面催化','电催化','生物质转化','催化选择性','反应路径搜索','过渡态搜索','全局优化','机器学习势','自动化工作流','分子动力学','材料电子结构','领域待分类'];
const COMMON_STRENGTH_TYPES=['技术创新','科学构想','效率提升','机制证据','工程验证','数据与工具','其他贡献'];
function multiOptions(values,selected){return values.map(x=>`<option value="${esc(x)}" ${selected.includes(x)?'selected':''}>${esc(x)}</option>`).join('');}
function openPaperEdit(id){const p=paper(id);if(!p)return;const editableSummary=typeof p.summary==='string'?{researchQuestion:p.summary,mainFindings:p.keyFindings||[],novelty:p.novelty||'',limitations:p.limitations||[]}:p.summary||p.analysis?.summary||{};const insight=p.insight||{},selectedFields=getPaperTaxonomy(p).fields,fields=[...new Set([...COMMON_RESEARCH_FIELDS,...state.papers.flatMap(x=>getPaperTaxonomy(x).fields)])].sort((a,b)=>a.localeCompare(b,'zh-CN')),strengths=normalizeResearchFields(insight.strengthTypes),types=[...new Set([...COMMON_STRENGTH_TYPES,...strengths])];modal('编辑文献信息与研读判断',`<form id="paper-form"><div class="form-grid">${field('完整中文原题','title',p.title,'text','required maxlength="400"')}${field('中文短名（展示名称）','shortTitle',paperShortName(p),'text','required maxlength="80"')}${field('英文原标题','englishTitle',p.englishTitle||'','text','maxlength="800"')}${field('作者（用分号分隔）','authors',(p.authors||[]).join('; '),'text','maxlength="2000"')}${field('期刊','journal',p.journal||'','text','maxlength="200"')}${field('发表年份','year',p.year||'','text','maxlength="20"')}${field('DOI','doi',p.doi||'','text','maxlength="200" placeholder="10.xxxx/xxxxx"')}<label class="field"><span>科学问题研究类型</span><select class="select" name="studyType"><option value="待分类">待分类</option>${STUDY_TYPES.map(type=>`<option ${paperStudyType(p)===type?'selected':''}>${type}</option>`).join('')}</select></label><label class="field"><span>研究领域（可多选）</span><select class="select taxonomy-multiselect" name="researchFields" multiple size="5">${multiOptions(fields,selectedFields)}</select><small class="helper">可同时归入多个子列表；按 Ctrl / Command 多选。</small></label><label class="field"><span>突出贡献类型（可多选）</span><select class="select taxonomy-multiselect" name="strengthTypes" multiple size="5">${multiOptions(types,strengths)}</select></label>${area('这篇论文最牛的地方：判断摘要','insightHighlight',insight.highlight||'','maxlength="1500"')}${area('判断理由与原文依据','insightReasoning',insight.reasoning||'','maxlength="6000"')}${area('科学问题','scientificQuestion',insight.scientificQuestion||'','maxlength="3000"')}${area('论文对科学问题的回答','scientificAnswer',p.scientificAnswer||'','maxlength="5000"')}${area('中文解读：研究问题','summaryQuestion',editableSummary.researchQuestion||'','maxlength="8000"')}${area('中文解读：主要发现（每行一项）','summaryFindings',(editableSummary.mainFindings||[]).join('\n'),'maxlength="20000"')}${area('中文解读：创新与机制线索','summaryNovelty',editableSummary.novelty||'','maxlength="8000"')}${area('中文解读：适用边界（每行一项）','summaryLimitations',(Array.isArray(editableSummary.limitations)?editableSummary.limitations:[editableSummary.limitations||'']).join('\n'),'maxlength="12000"')}${field('判断证据 PDF 页码（逗号分隔）','insightPages',(insight.evidencePages||[]).join(', '),'text','maxlength="150"')}${area('适用边界与不能推出的结论','insightCaveat',insight.caveat||'','maxlength="3000"')}${field('研究标签（逗号分隔）','tags',(p.tags||[]).join(', '),'text','maxlength="150"')}${field('DOI / 全文链接（完整网址）','url',p.url||'','url','placeholder="https://doi.org/…"')}</div><p class="helper assessment-editor-source">判断来源：${esc(insight.assessmentSource||'待研读')}<br>人工修改会保存在当前浏览器，并优先于后续 AI 解读。</p><div class="dialog-footer"><button class="button secondary" type="button" data-action="paper" data-id="${id}">返回</button><button class="button primary" type="submit">保存信息与判断</button></div></form>`,{wide:true});$('#paper-form').onsubmit=async e=>{e.preventDefault();const d=new FormData(e.target);try{const next=structuredClone(state),target=next.papers.find(p=>p.id===id);target.title=d.get('title').trim();target.chineseTitle=target.title;if(d.has('shortTitle')){target.shortTitle=d.get('shortTitle').trim();target.shortTitleEdited=true;}if(!target.title)throw new Error('请填写中文论文标题。');for(const key of ['englishTitle','journal','year','doi'])target[key]=d.get(key).trim();target.authors=d.get('authors').split(/[;；]/).map(s=>s.trim()).filter(Boolean);target.tags=d.get('tags').split(/[,，]/).map(s=>s.trim()).filter(Boolean);target.url=safeURL(d.get('url'));target.studyType=d.get('studyType');target.researchFields=normalizeResearchFields(d.getAll('researchFields'));const evidencePages=d.get('insightPages').split(/[,，;；、\s]+/).filter(Boolean).map(Number);if(evidencePages.some(n=>!Number.isInteger(n)||n<1||n>target.pages))throw new Error(`证据页码须在 1–${target.pages} 之间。`);target.insight={...target.insight,strengthTypes:normalizeResearchFields(d.getAll('strengthTypes')),highlight:d.get('insightHighlight').trim(),reasoning:d.get('insightReasoning').trim(),scientificQuestion:d.get('scientificQuestion').trim(),evidencePages:[...new Set(evidencePages)],caveat:d.get('insightCaveat').trim(),assessmentSource:'人工研读判断（已编辑），非作者原话或官方评价。'};target.scientificAnswer=d.get('scientificAnswer').trim();target.summary={researchQuestion:d.get('summaryQuestion').trim(),mainFindings:d.get('summaryFindings').split(/\r?\n/).map(x=>x.trim()).filter(Boolean),novelty:d.get('summaryNovelty').trim(),limitations:d.get('summaryLimitations').split(/\r?\n/).map(x=>x.trim()).filter(Boolean)};target.manualEdited=true;target.taxonomyEdited=true;target.insightEdited=true;await commit(next);openPaper(id);toast('文献信息、领域与研读判断已保存');}catch(err){toast(err.message);}};}

function openNote(figureId='',noteId=''){const existing=state.notes.find(n=>n.id===noteId);const f=figure(existing?.figureId||figureId);modal(noteId?'编辑我的灵感':'记下一个新想法',`<form id="note-form">${f?`<div class="source-box"><span class="note-source">${icon('link',16)} ${esc(f.number)} · ${esc(figureDisplayTitle(f))} · p. ${f.page}</span></div>`:''}<div class="form-grid">${area('我的想法 / 写作借鉴','text',existing?.text||'','required maxlength="20000" autofocus placeholder="这张图给了我什么启发？我想验证什么？可以怎样用于自己的图组或论证？"')}${field('标签（逗号或 / 分隔）','tags',existing?.tags||'','text','placeholder="机制解释 / 待验证 / 图组设计" maxlength="200"')}</div><p class="helper">这里保存你的观点与假设，请将论文作者的结论写在图表解读中。</p><div class="dialog-footer"><button class="button secondary" type="button" data-action="close">取消</button><button class="button primary" type="submit">${icon('check',16)} 保存灵感</button></div></form>`);$('#note-form').onsubmit=async e=>{e.preventDefault();const d=new FormData(e.target);const text=d.get('text').trim();if(!text)return toast('先写下一点想法吧');try{const next=structuredClone(state);const n={id:existing?.id||uid(),figureId:f?.id||'',paperId:f?.paperId||existing?.paperId||'',text,tags:d.get('tags').trim(),createdAt:existing?.createdAt||today(),demo:false,aiGenerated:false};if(existing)next.notes=next.notes.map(v=>v.id===existing.id?n:v);else next.notes.unshift(n);await commit(next);closeModal();toast('灵感已保存在本地工作区');}catch(err){toast('保存失败：'+err.message);}};}
function openMethod(id='',context=null){const m=state.methods.find(m=>m.id===id)||{paperId:context?.paperId,page:context?.page};const ps=visible(state.papers),missingSource=!!m.id&&!ps.some(p=>p.id===m.paperId);if(!ps.length){toast('请先导入一篇论文，再记录计算方法');return openUpload();}modal(id?'编辑计算方法':'记录一套计算方法',`<form id="method-form"><div class="form-grid">${field('方法名称','title',m.title||'','text','required maxlength="200" placeholder="例如：RuO₂ 表面吸附能计算"')}${field('软件 / 模块','software',m.software||'','text','maxlength="120" placeholder="例如：VASP / CI-NEB"')}<label class="field"><span>来源文献</span><select class="select" name="paperId" required>${missingSource?'<option value="" selected disabled>请选择来源文献（原来源不可用）</option>':''}${ps.map(p=>`<option value="${p.id}" ${m.paperId===p.id?'selected':''}>${esc(displayPaperTitle(p))}</option>`).join('')}</select></label>${field('证据所在 PDF 页码','page',m.id&&m.page==null?'':m.page||1,'number','required min="1" placeholder="原文页码待核实"')}<fieldset class="field full method-category-editor"><legend>方法分类（可多选）</legend>${METHOD_CATEGORIES.map(c=>`<label><input type="checkbox" name="categories" value="${esc(c)}" ${getMethodCategories(m).includes(c)?'checked':''}> ${esc(c)}</label>`).join('')}</fieldset>${area('步骤与参数记录','parameters',m.parameters||'','required maxlength="20000" placeholder="软件版本、泛函、赝势、截断能、k 点、自旋、色散、U值、收敛阈值、修正方法…\n没有在原文中找到的设置，请写“待核实”。"')}${area('原文证据 / SI位置 / 待核实事项','evidence',m.evidence||'','maxlength="10000"')}</div><div class="dialog-footer"><button class="button secondary" type="button" data-action="close">取消</button><button class="button primary" type="submit">保存方法</button></div></form>`);$('#method-form').onsubmit=async e=>{e.preventDefault();const d=new FormData(e.target);try{const source=paper(d.get('paperId'));if(!source||isPaperRemoved(source.id))throw new Error('请选择当前库中的来源文献。');await ensurePersonalPaper(source.id);const page=Number(d.get('page'));if(!Number.isInteger(page)||page<1||page>source.pages)throw new Error(`页码须在 1–${source.pages} 之间。`);if(!d.get('title').trim()||!d.get('parameters').trim())throw new Error('请填写方法名称与参数记录。');const next=structuredClone(state);const item={...m,...Object.fromEntries(d),categories:d.getAll('categories'),categoriesEdited:true,id:m.id||uid(),page,manualEdited:true};if(m.id)next.methods=next.methods.map(v=>v.id===m.id?item:v);else next.methods.unshift(item);await commit(next);closeModal();toast('计算方法与证据位置已保存');}catch(err){toast(err.message);}};}
function editableFigureTags(f){if(!identity.authenticated)return figureTagsHTML(f);return `<div class="figure-editable-tags">${getFigureTags(f).map(t=>`<span class="tag-chip">${esc(t)}<button type="button" data-action="figure-tag-remove" data-id="${esc(f.id)}" data-tag="${esc(t)}" aria-label="删除标签 ${esc(t)}">×</button></span>`).join('')||'<span class="helper">暂无标签，可以自由添加</span>'}</div><div class="figure-tag-add"><input class="input" id="figure-tag-input" maxlength="800" placeholder="添加标签，多个用逗号分隔" aria-label="新增图表标签"><button class="button secondary" id="figure-tag-add" data-action="figure-tag-add" data-id="${esc(f.id)}">添加</button></div>`;}
async function updateFigureTags(id,tags){assertWritableWorkspace();const next=structuredClone(state),f=next.figures.find(x=>x.id===id);if(!f)throw Error('未找到这张个人图表，请重新打开。');Object.assign(f,{tags:normalizeTags(tags),tagsEdited:true,manualEdited:true});await commit(next);openFigure(id);toast('图表标签已保存');}
async function copyFigureImage(id,button){const f=figure(id),url=f&&figureImage(f,paper(f.paperId));if(!url)return toast('这张图暂无可复制的图片。');if(!navigator.clipboard?.write||typeof ClipboardItem==='undefined')return toast('当前浏览器不支持复制图片，请使用图片右键菜单复制。');if(button)button.disabled=true;
 try{const png=(async()=>{const r=await fetch(url,{credentials:'same-origin'});if(!r.ok)throw Error('图片读取失败');const blob=await r.blob();if(blob.type==='image/png')return blob;const bitmap=await createImageBitmap(blob);try{const canvas=document.createElement('canvas');canvas.width=bitmap.width;canvas.height=bitmap.height;canvas.getContext('2d').drawImage(bitmap,0,0);const out=await new Promise(ok=>canvas.toBlob(ok,'image/png'));if(!out)throw Error('图片转换失败');return out;}finally{bitmap.close();}})();await navigator.clipboard.write([new ClipboardItem({'image/png':png})]);toast('图片已复制，可粘贴到 Word 等文档');}catch(e){toast(e.name==='NotAllowedError'?'请允许浏览器访问剪贴板后重试。':'复制图片未完成：'+e.message);}finally{if(button?.isConnected)button.disabled=false;}}
function openFigureEditor(id='',crop=null){const f=state.figures.find(f=>f.id===id)||crop;if(!f)return;pendingCrop=crop;modal(id?'编辑图表解读':'收集这张图表',`<form id="figure-form"><div class="figure-edit-preview">${figureImage(f)?`<img src="${esc(figureImage(f))}" alt="待保存的图表">`:sourceFigurePlaceholder(paper(f.paperId))}</div><div class="form-grid">${field('图表标题','title',f.title||'','text','required maxlength="250" placeholder="用一句话概括这张图的用途"')}${field('原文图号','number',f.number||'','text','required maxlength="60" placeholder="例如 Fig. 2b"')}<label class="field"><span>图表分类</span><select class="select" name="category">${allCategories().slice(1).map(c=>`<option ${f.category===c?'selected':''}>${c}</option>`).join('')}</select></label>${field('计算方法（可选）','method',f.method||'','text','maxlength="150" placeholder="DFT · 自由能修正"')}${field('来源 PDF 页码','page',f.page||1,'number',`required min="1" max="${paper(f.paperId)?.pages||1}"`)}<label class="field field-full"><span>画法与内容标签（逗号分隔，可多选）</span><input class="input" name="tags" value="${esc(getFigureTags(f).join(', '))}" maxlength="800" placeholder="例如：自由能图, 球棍结构, 多面板组合"><small class="helper">可保留多个画法和技术标签；同义标签会自动归一，清空后不再补默认标签。</small></label>${area('原文英文图注','captionOriginal',figureCaptionOriginal(f,paper(f.paperId)),'maxlength="20000" placeholder="原论文英文图注，可直接粘贴；显示在图片下方。"')}${area('原文图注中文译文','captionZh',figureCaptionZh(f,paper(f.paperId)),'maxlength="20000" placeholder="填写原文图注的完整中文翻译；未核实可留空，不会用简短说明代替。"')}${area('简短说明','description',f.description||'','maxlength="1000"')}${area('这张图在回答什么','question',f.question||'','maxlength="5000"')}${area('坐标、图例与阅读方式','reading',f.reading||'','maxlength="5000"')}${area('关键观察 / 原文结论','finding',f.finding||'','maxlength="5000"')}${area('适用条件与待核实项','limits',f.limits||'','maxlength="5000"')}</div><p class="helper">未填写的解读会显示为“待记录”，不会自动生成研究结论。</p><div class="dialog-footer"><button class="button secondary" type="button" data-action="close">取消</button><button class="button primary" type="submit">${icon('check',16)} 保存图表与解读</button></div></form>`,{wide:true});$('#figure-form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{if(!d.title.trim()||!d.number.trim())throw new Error('请填写图表标题和原文图号。');d.page=Number(d.page);d.tags=normalizeTags(d.tags);const p=paper(f.paperId);if(!Number.isInteger(d.page)||d.page<1||d.page>p.pages)throw new Error('请填写有效的PDF页码。');const next=structuredClone(state),item={...f,...d,title:d.title.trim(),number:d.number.trim(),id:f.id||uid(),saved:!!f.saved,manualEdited:true,tagsEdited:true,captionZh:d.captionZh.trim(),captionEdited:true};if(id)next.figures=next.figures.map(x=>x.id===id?item:x);else next.figures.unshift(item);await commit(next);openFigure(item.id);toast('图表与中文解读已保存');}catch(err){toast('保存失败：'+err.message);}};}
async function getPDF(data){if(!pdfLib){pdfLib=await import('./vendor/pdfjs/legacy/build/pdf.min.mjs');pdfLib.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdfjs/legacy/build/pdf.worker.min.mjs',import.meta.url).href;}return pdfLib.getDocument({data,cMapUrl:new URL('./vendor/pdfjs/cmaps/',import.meta.url).href,cMapPacked:true,standardFontDataUrl:new URL('./vendor/pdfjs/standard_fonts/',import.meta.url).href,wasmUrl:new URL('./vendor/pdfjs/wasm/',import.meta.url).href,isEvalSupported:false}).promise;}
function openUpload({returnTo='papers'}={}){uploadReturnView=returnTo;uploadFile=null;uploadFiles=[];modal('上传论文 · 自动中文解读',`<form id="upload-form"><label class="upload-zone" id="drop-zone" tabindex="0"><input id="pdf-input" type="file" accept="application/pdf,.pdf" multiple hidden><span class="upload-icon">${icon('upload',32)}</span><strong id="upload-name">拖入一篇或多篇 PDF，或点击选择文件</strong><span id="upload-size">${cloud.storageEnabled?'支持多选 · 每批最多50篇 · 单篇25 MB、100页':'本地阅读：最大 50 MB；云端暂不可用'}</span></label><div class="form-grid upload-fields">${field('论文原题（AI 完成后提取中文译名）','title','','text','required maxlength="400" placeholder="选择文件后自动填入，AI 将提取并翻译原始题名"')}${field('研究标签（逗号分隔）','tags','','text','maxlength="150" placeholder="DFT, 表面催化, 电催化"')}${field('DOI / 全文链接（可选）','url','','url','placeholder="https://doi.org/…"')}</div><p class="hint">${cloud.aiEnabled?'直接上传 PDF 即可生成中文题名、来源信息、论文解读、计算步骤与图表说明。展示名称统一为“年份 期刊名 中文短名”，完整原题另行保留。原文件和 AI 解读保存到私有在线工作区；AI 草稿需要对照原文核对。':'上传后由网站自动准备文档，无需安装软件或手动预处理。PDF 可直接阅读和框选图表。登录后原 PDF、待解读记录、预处理记录和色卡会同步到私人云端；AI 解读可稍后启用。'}</p><div id="upload-progress" role="status" class="helper"></div><div class="dialog-footer"><button class="button secondary" type="button" data-action="close">取消</button><button id="upload-submit" class="button primary" type="submit">${icon(cloud.aiEnabled?'spark':'upload',17)} ${cloud.aiEnabled?'上传并 AI 解读':'导入并打开'}</button></div></form>`,{kind:'upload'});const zone=$('#drop-zone');$('#pdf-input').onchange=e=>chooseFiles([...e.target.files]);zone.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('#pdf-input').click();}};zone.ondragover=e=>{e.preventDefault();zone.classList.add('drag-over');};zone.ondragleave=()=>zone.classList.remove('drag-over');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('drag-over');chooseFiles([...e.dataTransfer.files]);};$('#upload-form').onsubmit=submitUploadSelection;}

function chooseFiles(files){if(importJob&&!importJob.cancelled)return toast('正在导入，取消后可重新选择文件');if(!files.length)return;uploadFiles=files;if(files.length===1){chooseFile(files[0]);return;}uploadFile=null;$('#upload-name').textContent=`已选择 ${files.length} 份文件`;
 $('#upload-size').textContent='逐篇查重，重复跳过；每篇最大25MB、100页。研究标签将应用到本批文件。';for(const name of ['title','url'])$('#upload-form [name="'+name+'"]').disabled=true;$('#upload-submit').textContent=cloud.aiEnabled?'批量上传并自动解读':'批量保存到工作区';}
function submitUploadSelection(e){if(uploadFiles.length>1||paperBatch.isRunning()){e.preventDefault();try{assertWritableWorkspace();const form=new FormData(e.target);paperBatch.addFiles(uploadFiles,{tags:String(form.get('tags')||'').split(/[,，]/).map(s=>s.trim()).filter(Boolean)});closeModal();view='pending';history.replaceState(null,'','#pending');render();toast('已加入批量队列，重复文献自动跳过。');}catch(error){toast(error.message);}return;}return importPDF(e);}
function assertBatchAccount(owner){assertWritableWorkspace();if(identity.userStorageKey!==owner)throw Error('账号已切换，已停止提交此批文件。');}
async function submitBatchFile(item,report,owner){assertBatchAccount(owner);const file=item.file;if(!/\.pdf$/i.test(file.name))throw Error('仅支持PDF，已跳过此文件。');if(!file.size||file.size>(cloud.maxUploadBytes||25*1024*1024))throw Error('PDF必须非空且不超过25MB。');let doc,documentIdentity,pages;report('正在读取PDF并查重…');try{const bytes=new Uint8Array(await file.arrayBuffer());if(!new TextDecoder().decode(bytes.slice(0,1024)).includes('%PDF-'))throw Error('文件内容不是有效PDF。');const sha=await pdfSHA256(bytes);doc=await getPDF(bytes);pages=doc.numPages;if(pages>100)throw Error('每篇最多100页，请拆分后上传。');documentIdentity=await identityFromPDF(doc,sha);const duplicate=findPaperDuplicate(documentIdentity,state.papers.filter(p=>!p.demo));if(duplicate){const error=Error('重复文献：文献库或工作区已有此论文，未再次解读。');error.code='DUPLICATE_PAPER';error.details={existing:{paperId:duplicate.paper.id}};throw error;}}finally{await doc?.loadingTask.destroy();}
 assertBatchAccount(owner);await checkCloudDuplicate(documentIdentity);assertBatchAccount(owner);let prepared={};if(item.analyze){report('正在本地准备原文与图表，减少服务器等待…');prepared=await prepareForAI({id:item.requestId,title:file.name,pages},file);assertBatchAccount(owner);}report(item.analyze?'正在上传并提交后台解读…':'正在保存到私人云端…');let result;try{result=await uploadCloudPaper(file,{title:file.name.replace(/\.pdf$/i,''),tags:item.tags,pageCount:pages,requestId:item.requestId,analyze:item.analyze,analysisPacket:prepared.analysisPacket});}catch(error){if(error.code==='DUPLICATE_PAPER')throw error;try{result=await cloudPaper(item.requestId);}catch{}if(!result)throw error;}
 assertBatchAccount(owner);item.paperId=result.paper.id;await mergeCloudDetail(result,{file});scheduleCloudPoll(result.paper.id);if(result.paper.status==='failed')throw Object.assign(Error(result.paper.error?.message||'解读提交未完成，PDF已保存。'),{code:result.paper.error?.code});return {paperId:result.paper.id,message:item.analyze?'已提交后台解读':'PDF已保存到工作区'};}
function pendingEligible(p){return p.error?.code!=='AI_START_UNCERTAIN'&&isPendingPaper(p)&&!['queued','processing'].includes(p.status)&&(p.status!=='failed'||canRetryAnalysis(p,{allowUnconfirmed:true}));}
function pendingBatchTools(list){if(!cloud.aiEnabled)return '';const eligible=list.filter(pendingEligible),count=eligible.filter(p=>pendingSelection.has(p.id)).length;return `<div class="pending-batch-tools"><label><input type="checkbox" id="pending-select-all" ${eligible.length&&count===eligible.length?'checked':''} ${eligible.length?'':'disabled'}> 全选可解读文献</label><span>已选 ${count} 篇</span><button class="button primary" id="pending-batch-start" ${count?'':'disabled'}>批量开始解读</button><p>已在解读中的任务不会重复提交。</p></div>`;}
function bindPendingBatch(){for(const box of document.querySelectorAll('[data-pending-select]'))box.onchange=()=>{if(box.checked)pendingSelection.add(box.dataset.pendingSelect);else pendingSelection.delete(box.dataset.pendingSelect);renderContent();};$('#pending-select-all')?.addEventListener('change',e=>{for(const p of visible(state.papers).filter(isPendingPaper).filter(paperSearch).filter(pendingEligible)){if(e.target.checked)pendingSelection.add(p.id);else pendingSelection.delete(p.id);}renderContent();});$('#pending-batch-start')?.addEventListener('click',()=>{try{const selected=visible(state.papers).filter(isPendingPaper).filter(paperSearch).filter(p=>pendingSelection.has(p.id)&&pendingEligible(p));paperBatch.addPapers(selected);for(const p of selected)pendingSelection.delete(p.id);renderContent();}catch(e){toast(e.message);}});}
async function submitBatchPaper(item,report,owner){assertBatchAccount(owner);let p=paper(item.paperId);if(!p)throw Error('此文献已移除。');if(p.taskDeletedAt)return {paperId:p.id,skipped:true,message:'任务已删除，未提交AI。'};if(hasPaperAnalysis(p))return {paperId:p.id,skipped:true,message:'已有解读，已跳过。'};if(['queued','processing'].includes(p.status))return {paperId:p.id,skipped:true,message:'已在后台解读，未重复提交。'};report('正在检查并提交后台解读…');let result;if(p.cloud){const blob=await getPaperBlob(p),prepared=blob?await prepareForAI(p,blob):{};assertBatchAccount(owner);result=await startCloudPaperAnalysis(p.id,prepared.analysisPacket);}else{const file=await getPaperBlob(p);if(!file)throw Error('找不到原始PDF，请在最初上传的电脑上同步。');result=await uploadCloudPaper(file,{title:p.title,tags:p.tags||[],pageCount:p.pages,requestId:p.requestId||p.id,analyze:true,metadata:paperUploadMetadata(p)});assertBatchAccount(owner);await mergeCloudDetail(result,{replaceLocalId:p.id,file});}assertBatchAccount(owner);if(p.cloud)await mergeCloudDetail(result);scheduleCloudPoll(result.paper.id);if(result.paper.status==='failed')throw Error(result.paper.error?.message||'解读未启动，请查看记录。');return {paperId:result.paper.id};}

function chooseFile(file){if(importJob&&!importJob.cancelled)return toast('正在导入，取消后可重新选择文件');if(!file)return;if(!/\.pdf$/i.test(file.name))return toast('请选择 PDF 文件');if(file.size>50*1024*1024)return toast('文件超过 50 MB，请先压缩或拆分');uploadFiles=[file];for(const name of ['title','url'])$('#upload-form [name="'+name+'"]').disabled=false;$('#upload-submit').textContent=cloud.aiEnabled?'上传并 AI 解读':'导入并打开';uploadFile=file;$('#upload-name').textContent=file.name;$('#upload-size').textContent=`${(file.size/1024/1024).toFixed(2)} MB · 已选择，等待导入`;$('#upload-form [name="title"]').value=file.name.replace(/\.pdf$/i,'').replace(/[_-]/g,' ');}
async function discardDuplicateDraft(id){const p=state.papers.find(p=>p.id===id);if(!p||p.cloud||seedPaperIds.has(id))return;const next=structuredClone(state);next.papers=next.papers.filter(p=>p.id!==id);await commit(next);if(db)await new Promise((resolve,reject)=>{const tx=db.transaction('entries','readwrite');tx.objectStore('entries').delete('pdf:'+id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
async function uploadNativePDF(file,form,pages,job,onProgress){const localId=uid(),requestId=uid(),item={documentIdentity:job.documentIdentity,sourceSha256:job.documentIdentity?.sha256,id:localId,requestId,title:form.get('title').trim(),filename:file.name,tags:form.get('tags').split(/[,，]/).map(x=>x.trim()).filter(Boolean),url:safeURL(form.get('url')),pages,status:'pending',createdAt:today(),demo:false};const next=structuredClone(state);next.papers.unshift(item);await commit(next,[[`pdf:${localId}`,file]]);onProgress(cloud.aiEnabled?'正在上传PDF并启动云端解读…':'正在保存PDF到个人工作区…');let result;try{result=await uploadCloudPaper(file,{title:item.title,tags:item.tags,pageCount:pages,requestId,analyze:cloud.aiEnabled,metadata:paperUploadMetadata(item)});}catch(error){if(error.code==='DUPLICATE_PAPER'){await discardDuplicateDraft(localId);throw error;}try{result=await cloudPaper(requestId);}catch{}if(!result)throw error;}await mergeCloudDetail(result,{replaceLocalId:localId,file});scheduleCloudPoll(result.paper.id);if(job.cancelled)return;importJob=null;closeModal();view=hasPaperAnalysis(paper(result.paper.id)||{})?'papers':'pending';history.replaceState(null,'','#'+view);render();openPaper(result.paper.id);toast(cloud.aiEnabled?'PDF已保存，云端正在自动解读，可关闭页面后回来查看。':'PDF已保存到个人工作区。');}

async function importPDF(e) {
  e.preventDefault();
  const file=uploadFile;if(!file)return toast('请先选择一份PDF');
  const form=e.target,d=new FormData(form),button=$('#upload-submit'),progress=$('#upload-progress');
  if(!d.get('title').trim())return toast('请填写论文标题');
  if(cloud.storageEnabled&&file.size>cloud.maxUploadBytes)return toast('云端同步支持最大 25 MB，请压缩或拆分 PDF 后上传。');
  const job={cancelled:false};importJob=job;button.disabled=true;$('#pdf-input').disabled=true;
  let doc,localId;
  try {
    const url=safeURL(d.get('url'));progress.textContent='正在读取 PDF 与核对页码…';
    const bytes=new Uint8Array(await file.arrayBuffer());if(job.cancelled)return;
    if(!new TextDecoder().decode(bytes.slice(0,1024)).includes('%PDF-'))throw new Error('文件不是有效的PDF。');
    const sourceSha256=await pdfSHA256(bytes);doc=await getPDF(bytes);if(job.cancelled)return;progress.textContent='正在核对文件指纹、DOI和题名…';job.documentIdentity=await identityFromPDF(doc,sourceSha256,{url});const duplicate=findPaperDuplicate(job.documentIdentity,state.papers.filter(p=>!p.demo));if(duplicate){const error=new Error('重复文献：已存在于文献库或当前工作区，不会再次导入。');error.code='DUPLICATE_PAPER';error.details={existing:{paperId:duplicate.paper.id}};throw error;}if(cloud.online&&cloud.storageEnabled)await checkCloudDuplicate(job.documentIdentity);
    const pages=doc.numPages;if(cloud.storageEnabled&&pages>100)throw new Error('云端单份支持最多100页，请先拆分正文与附件。');
    if(cloud.online&&cloud.storageEnabled&&cloud.automaticPDFPreparation&&!cloud.aiEnabled){await uploadNativePDF(file,d,pages,job,message=>{if(progress.isConnected)progress.textContent=message;});return;}
    let texts,preflight,analysisPacket=null;
    try{const prepared=await preprocessPDF(doc,{onProgress:message=>progress.textContent=message,cancelled:()=>job.cancelled});texts=prepared.texts;preflight=prepared.preflight;if(cloud.aiEnabled)analysisPacket=await buildAnalysisPacket(doc,preflight,{onProgress:message=>progress.textContent=message,forcePages:cloud.aiProvider==='zhipu',ops:pdfLib.OPS});}catch(error){if(job.cancelled)return;if(cloud.online&&cloud.storageEnabled&&cloud.automaticPDFPreparation){await uploadNativePDF(file,d,pages,job,message=>{if(progress.isConnected)progress.textContent=message;});return;}throw error;}
    if(cloud.aiEnabled&&!analysisPacket&&cloud.automaticPDFPreparation){await uploadNativePDF(file,d,pages,job,message=>{if(progress.isConnected)progress.textContent=message;});return;}
    preflight.mode=analysisPacket?'text-and-figure-pages':'original-pdf';
    if(job.cancelled)return;
    progress.textContent='正在从论文页面提取配色…';
    let palette=null;
    try{palette=await extractPaletteFromPdf(doc,{onProgress:({done,total})=>{if(job.cancelled)throw new DOMException('已取消','AbortError');progress.textContent=`正在提取配色 ${done} / ${total} 页…`;}});}catch(error){if(job.cancelled)return;}
    if(job.cancelled)return;
    const item={documentIdentity:job.documentIdentity,sourceSha256:job.documentIdentity?.sha256,palette,preflight,id:uid(),requestId:uid(),title:d.get('title').trim(),filename:file.name,tags:d.get('tags').split(/[,，]/).map(x=>x.trim()).filter(Boolean),url,pages,pageTexts:texts,status:'待解读',createdAt:today(),demo:false};localId=item.id;
    progress.textContent='正在保存 PDF…';const next=structuredClone(state);next.papers.unshift(item);await commit(next,[[`pdf:${item.id}`,file]]);
    if(job.cancelled)return;
    await doc.loadingTask.destroy();doc=null;
    let resultId=item.id;
    if(cloud.storageEnabled&&cloud.online){progress.textContent='正在同步 PDF 到私人云端…';resultId=await syncPaperToCloud(item.id,{rejectDuplicates:true})||item.id;}
    if(cloud.aiEnabled){
      progress.textContent='正在上传到私有文献库并提交 AI 任务…';
      try{const result=await uploadCloudPaper(file,{title:item.title,tags:item.tags,pageCount:pages,requestId:item.requestId,analysisPacket,metadata:paperUploadMetadata(item)});resultId=result.paper.id;await mergeCloudDetail(result,{replaceLocalId:item.id,file});scheduleCloudPoll(resultId);}
      catch(error){const failed=structuredClone(state),p=failed.papers.find(p=>p.id===resultId);if(p)p.error={code:error.code||'UPLOAD_FAILED',message:error.message};await commit(failed);if(!job.cancelled)toast('已保留 PDF。在线解读提交未完成：'+error.message);}
    }
    if(job.cancelled)return;
    importJob=null;closeModal();view=uploadReturnView==='admin'&&identity.isCatalogAdmin?'admin':hasPaperAnalysis(paper(resultId)||{})?'papers':'pending';if(view==='admin')adminPaperId=resultId;history.replaceState(null,'','#'+view);render();
    if(paper(resultId)?.cloud){toast(!identity.isCatalogAdmin?'已保存到你的个人文献库，公共库准入由管理员审核。':paper(resultId).status==='pending'?'已同步到私人云端，其他电脑登录同一账号即可查看。':'论文已上传，AI 正在生成中文解读。');openPaper(resultId);}
    else{toast(`已导入 ${pages} 页 PDF；当前仅保存在本机，请检查云端同步状态。`);openPaper(resultId);}
  } catch(error){if(error.code==='DUPLICATE_PAPER'&&localId)await discardDuplicateDraft(localId);if(!job.cancelled){toast('导入失败：'+(error.name==='PasswordException'?'请使用已解密的PDF。':error.message));if(progress.isConnected){if(error.code==='DUPLICATE_PAPER'){const existingId=error.details?.existing?.paperId;progress.innerHTML=`<span>${esc(error.message)}</span>${existingId&&paper(existingId)?` <button type="button" class="button secondary" data-action="paper" data-id="${esc(existingId)}">查看已有文献</button>`:''}`;}else progress.textContent='未完成导入，请检查文件后重试。';}}}
  finally{if(doc)await doc.loadingTask.destroy();if(importJob===job)importJob=null;if(button.isConnected){button.disabled=false;$('#pdf-input').disabled=false;}}
}
async function openPDF(id,page=1,{replaceFigureId=''}={}){const p=paper(id);if(!p||isPaperRemoved(id))return;closeModal({syncRoute:false});
 if(p.releaseAccess?.originalPdf===false){
  const url=sourceUrl(p), pageLabel=Number.isInteger(Number(page))?` · 原 PDF 第 ${Number(page)} 页`:'';
  modal('查看原文来源',`<p class="detail-text">${esc(displayPaperTitle(p))}${esc(pageLabel)}</p><p class="helper">请通过出版社查看原文和原图。</p>${url?`<a class="button primary" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${icon('link',17)} 打开出版社原文</a>`:''}`);
  return;
 }
 if(replaceFigureId&&figure(replaceFigureId)?.paperId!==id)throw Error('待替换图片与原 PDF 不匹配。');
 modal(p.demo?'演示全文 · 计算催化图谱':p.title,`${replaceFigureId?`<div class="manual-crop-banner"><strong>正在替换：${esc(figureDisplayTitle(figure(replaceFigureId)))}</strong><span>选择页码后，在原图上拖动框线；松开后预览。</span>${figureRepairAIButton(replaceFigureId)}<button class="button secondary" data-action="manual-crop-cancel">取消勘误</button></div>`:''}<div class="pdf-toolbar"><div class="action-row"><button class="icon-button" data-action="pdf-prev" aria-label="上一页">${icon('chevron',17).replace('<svg ','<svg style="transform:rotate(180deg)" ')}</button><label class="pdf-page-label">第 <input class="input" id="pdf-page-input" type="number" min="1" max="${p.pages}" value="${page}" aria-label="PDF页码"> / ${p.pages} 页</label><button class="icon-button" data-action="pdf-next" aria-label="下一页">${icon('chevron',17)}</button></div><div class="action-row"><button class="icon-button" data-action="pdf-out" aria-label="缩小PDF">${icon('minus',17)}</button><span id="pdf-zoom-label" class="helper">100%</span><button class="icon-button" data-action="pdf-in" aria-label="放大PDF">${icon('plus',17)}</button><button class="button secondary" data-action="crop-toggle" id="crop-button">${icon('crop',16)} 框选图表</button></div></div><div class="pdf-layout"><div class="pdf-canvas-wrap" id="pdf-wrap"><p id="pdf-loading" class="helper">正在加载 PDF 原文…</p><div class="pdf-stage" id="pdf-stage" hidden><canvas class="pdf-canvas" id="pdf-canvas" aria-label="PDF页面"></canvas><div class="crop-overlay" id="crop-overlay" hidden><div class="crop-selection" id="crop-selection" hidden></div></div></div></div><aside class="pdf-sidebar"><span class="category-pill">可追溯的阅读</span><h3>${replaceFigureId?'框选并替换当前图':'把发现留在原文旁边'}</h3><p class="helper">${replaceFigureId?'可切换页码和缩放后重新框选；标题与中文解读将保留。':'点击「框选图表」，在页面上拖出一个矩形区域，即可收集图片并填写中文解释。'}</p><div class="source-box"><strong id="pdf-source-page">PDF 第 ${page} 页</strong><small>${p.demo?'交互演示文档 · 非真实研究':(p.cloud?'云端文件 · ':p.example?'原文全文 · ':'本地文件 · ')+esc(p.filename||'PDF')}</small></div><h4>本页提取文本</h4><p class="helper" id="pdf-text">加载后显示。扫描版PDF可能没有可提取文本。</p><button class="button secondary" data-action="method-new">${icon('flask',15)} 记录计算方法</button><button class="button ghost" data-action="pdf-download">${icon('download',15)} 下载原始 PDF</button></aside></div>`,{wide:true,kind:'pdf'});const current={paperId:id,replaceFigureId,page:Math.max(1,Math.min(p.pages,Number(page)||1)),zoom:1,token:1,doc:null,cropping:false,busy:false};reader=current;try{const blob=await getPaperBlob(p);if(!blob)throw new Error('此浏览器中找不到原始PDF，请重新导入文件。');current.blob=blob;const bytes=new Uint8Array(await blob.arrayBuffer());if(replaceFigureId)current.sourceSha256=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(b=>b.toString(16).padStart(2,'0')).join('');const doc=await getPDF(bytes);if(reader!==current){await doc.loadingTask.destroy();return;}current.doc=doc;await renderPDF();if(replaceFigureId&&!current.cropping)toggleCrop();$('#pdf-page-input').addEventListener('change',e=>goPage(Number(e.target.value)));}catch(err){if(reader===current){$('#pdf-loading').textContent='PDF打开失败：'+err.message;toast('PDF打开失败，请检查文件后重试');}}}
async function renderPDF(){const r=reader;if(!r?.doc||r.busy)return;r.busy=true;$('#pdf-wrap').setAttribute('aria-busy','true');const token=++r.token;try{const pg=await r.doc.getPage(r.page);if(reader!==r||r.token!==token)return;const wrap=$('#pdf-wrap'),base=pg.getViewport({scale:1}),available=Math.max(250,Math.min(850,wrap.clientWidth-48));const scale=available/base.width*r.zoom,display=pg.getViewport({scale}),ratio=Math.min(window.devicePixelRatio||1,2);const canvas=$('#pdf-canvas');const renderView=pg.getViewport({scale:scale*ratio});canvas.width=Math.floor(renderView.width);canvas.height=Math.floor(renderView.height);canvas.style.width=`${display.width}px`;canvas.style.height=`${display.height}px`;$('#pdf-stage').hidden=false;$('#pdf-loading').hidden=true;await pg.render({canvasContext:canvas.getContext('2d'),viewport:renderView}).promise;if(reader!==r||r.token!==token)return;$('#pdf-page-input').value=r.page;$('#pdf-source-page').textContent=`PDF 第 ${r.page} 页`;$('#pdf-zoom-label').textContent=Math.round(r.zoom*100)+'%';$('[data-action="pdf-prev"]').disabled=r.page<=1;$('[data-action="pdf-next"]').disabled=r.page>=r.doc.numPages;const text=await pg.getTextContent();if(reader!==r||r.token!==token)return;$('#pdf-text').textContent=text.items.map(i=>i.str||'').join(' ').slice(0,8000)||'本页没有可提取的文本，可能是扫描件。你仍可框选图表并手动记录解读。';attachCrop();if(r.replaceFigureId){r.cropping=true;$('#crop-overlay').hidden=false;$('#crop-button').classList.add('active');}}catch(err){if(reader===r)toast('页面渲染失败：'+err.message);}finally{r.busy=false;if(reader===r)$('#pdf-wrap')?.setAttribute('aria-busy','false');}}
async function goPage(num){if(!reader?.doc||reader.busy)return;const page=Math.max(1,Math.min(reader.doc.numPages,Math.round(num)||1));reader.page=page;reader.cropping=false;$('#crop-overlay').hidden=true;$('#crop-button').classList.remove('active');await renderPDF();}
function attachCrop(){const overlay=$('#crop-overlay'),select=$('#crop-selection');let start=null;const xy=e=>{const box=overlay.getBoundingClientRect();return {x:Math.max(0,Math.min(box.width,e.clientX-box.left)),y:Math.max(0,Math.min(box.height,e.clientY-box.top)),w:box.width,h:box.height};};overlay.onpointerdown=e=>{if(!reader?.cropping||reader.busy)return;e.preventDefault();start=xy(e);overlay.setPointerCapture(e.pointerId);select.hidden=false;select.style.cssText=`left:${start.x}px;top:${start.y}px;width:0;height:0`;};overlay.onpointermove=e=>{if(!start)return;const end=xy(e);select.style.cssText=`left:${Math.min(start.x,end.x)}px;top:${Math.min(start.y,end.y)}px;width:${Math.abs(end.x-start.x)}px;height:${Math.abs(end.y-start.y)}px`;};overlay.onpointercancel=()=>{start=null;select.hidden=true;};overlay.onpointerup=async e=>{if(!start||!reader)return;const end=xy(e),x=Math.min(start.x,end.x),y=Math.min(start.y,end.y),w=Math.abs(end.x-start.x),h=Math.abs(end.y-start.y);start=null;if(w<8||h<8){select.hidden=true;return toast('请拖出至少8像素的矩形选区');}const r=reader,bbox={x:x/end.w,y:y/end.h,width:w/end.w,height:h/end.h};r.busy=true;try{toast('正在从PDF生成高清选区…');const rendered=await renderPDFCrop(r.doc,r.page,bbox);if(reader!==r)return;if(r.replaceFigureId){openManualCropPreview({figureId:r.replaceFigureId,paperId:r.paperId,page:r.page,sourceSha256:r.sourceSha256,requestId:uid(),...rendered,bbox});return;}const f={paperId:r.paperId,page:r.page,...rendered,crop:bbox,category:categories[1],demo:!!paper(r.paperId)?.demo};closeModal();openFigureEditor('',f);}catch(error){if(reader===r)toast('选区生成失败：'+error.message);}finally{if(reader===r)r.busy=false;}};}
function toggleCrop(){if(!reader?.doc)return;reader.cropping=!reader.cropping;$('#crop-overlay').hidden=!reader.cropping;$('#crop-selection').hidden=true;$('#crop-button').classList.toggle('active',reader.cropping);if(reader.cropping)toast('在 PDF 页面上拖动，框选需要收集的图表');}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
