document.addEventListener('click',async e=>{if(document.body.classList.contains('sidebar-open')&&!e.target.closest('.sidebar,[data-action="menu"]')){document.body.classList.remove('sidebar-open');return;}const paperLink=e.target.closest('a[data-paper-route]');if(paperLink){if(e.button===0&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&!e.altKey){e.preventDefault();followPaperLink(paperLink);}return;}const cat=e.target.closest('[data-category]:not([data-action])');if(cat){category=cat.dataset.category;renderContent();return;}const n=e.target.closest('[data-view]');if(n){if(personalViews.has(n.dataset.view)&&!identity.authenticated)return;if(n.dataset.view==='admin'&&!identity.isCatalogAdmin)return;if(n.matches('a')){if(e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();}closeModal({syncRoute:false});activePaperRoute=null;catalogReadPaperId='';view=n.dataset.view;history.pushState(null,'',n.matches('a')?n.href:'#'+view);document.body.classList.remove('sidebar-open');render();if(n.dataset.section==='explore')focusFigureExplore();else window.scrollTo({top:0,behavior:'instant'});return;}const action=e.target.closest('[data-action]');if(action){try{await handleAction(action.dataset.action,action);}catch(err){console.error(err);toast('操作未完成：'+err.message);}return;}if(e.target===$('#modal'))closeModal();});
document.addEventListener('keydown',e=>{if(lightboxState){if(e.key==='Escape'){e.preventDefault();closeFigureLightbox();}if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();navigateFigure(e.key==='ArrowRight'?1:-1);return;}if(e.key==='Tab'){const buttons=[...$('#figure-lightbox').querySelectorAll('button:not(:disabled)')],first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}return;}if(modalKind==='paper'&&!e.altKey&&!e.ctrlKey&&!e.metaKey&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.activeElement.isContentEditable&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();navigatePaper(e.key==='ArrowRight'?1:-1);return;}if(modalKind==='figure'&&!e.altKey&&!e.ctrlKey&&!e.metaKey&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.activeElement.isContentEditable&&!document.activeElement.closest('.figure-rating')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();navigateFigure(e.key==='ArrowRight'?1:-1);return;}if(modalKind==='pdf'&&reader?.doc&&!reader.busy&&!e.altKey&&!e.ctrlKey&&!e.metaKey&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.activeElement.isContentEditable&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();goPage(reader.page+(e.key==='ArrowRight'?1:-1));return;}if(e.key==='Escape'){if(!$('#modal').hidden)closeModal();document.body.classList.remove('sidebar-open');}if(e.key==='/'&&$('#modal').hidden&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#global-search').focus();}if((e.key==='Enter'||e.key===' ')&&document.activeElement.matches('[role="button"][data-action]')){e.preventDefault();document.activeElement.click();}if(e.key==='Tab'&&!$('#modal').hidden){const focus=[...$('#modal').querySelectorAll('button:not(:disabled),a[href],input:not([hidden]),select,textarea,[tabindex="0"]')].filter(x=>x.getClientRects().length);const first=focus[0],last=focus.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',applyLocationRoute);
