 if(remote.taskDeletedAt){const next=structuredClone(state),p={...previous,...remote,cloud:true},i=next.papers.findIndex(p=>p.id===remote.id);if(i<0)next.papers.push(p);else next.papers[i]=p;await commit(next);return;}
