function scheduleCloudPoll(id,delay=5000){if(!identity.authenticated)return;if(cloudPolls.has(id))clearTimeout(cloudPolls.get(id));const p=paper(id);if(p?.taskDeletedAt||!p?.cloud||!['queued','processing'].includes(p.status)){cloudPolls.delete(id);return;}cloudPolls.set(id,setTimeout(()=>{cloudPolls.delete(id);refreshCloudPaper(id);},delay));}
const cloudRefreshing=new Set();
