const startingAnalyses=new Set();
async function openPDFRestore(id){
 const p=paper(id);if(!p)return;let file=await read(`pdf:${id}`);
 modal('补传原始PDF',`<p>网站已保留此文献记录，但原始PDF上传未完成。补传只保存文件，不启动AI。</p><p class="helper">${esc(p.filename||'请选择最初上传的同一份PDF')}</p><label class="field"><span>原始PDF</span><input type="file" id="restore-pdf-file" accept="application/pdf,.pdf"></label><p class="helper" id="restore-pdf-status">${file?'已找到本浏览器缓存的原PDF，可直接补传。':'请选择原文件，系统会校验是否与原记录一致。'}</p><button class="button primary" id="restore-pdf-submit" ${file?'':'disabled'}>补传到网站</button>`,{kind:'pdf-restore'});
 $('#restore-pdf-file').onchange=e=>{file=e.target.files[0];$('#restore-pdf-submit').disabled=!file;};
 $('#restore-pdf-submit').onclick=async()=>{const button=$('#restore-pdf-submit');button.disabled=true;try{const d=await restoreCloudPaperPDF(id,file);await mergeCloudDetail(d,{file});toast('原PDF已补传，尚未调用AI');openPaper(id);}catch(e){$('#restore-pdf-status').textContent=e.message;button.disabled=false;}};
}
async function startAI(id,{restartUnconfirmed=false}={}){
 assertWritableWorkspace();if(!cloud.aiEnabled){openAIStatus();return;}const p=paper(id);if(!p||startingAnalyses.has(id))return;if(p.pdfAvailable===false){await openPDFRestore(id);return;}
 if(p.error?.code==='AI_START_UNCERTAIN'&&!restartUnconfirmed){modal('确认重新启动这篇解读',`<p>原始PDF已保存。旧任务没有返回编号，因此无法确认是否已计费，也无法直接查询它的结果。</p><p class="helper">确认后会用已保存的PDF重新启动，并显示准备与提交进度。此操作可能产生一次新的模型调用费用。</p><button class="button primary" data-action="ai-retry-confirm" data-id="${esc(id)}">确认重新启动这篇解读</button>`,{kind:'ai-retry'});return;}startingAnalyses.add(id);
 modal('正在启动文献解读',`<div class="ai-progress"><span class="loading-spinner"></span><span id="ai-start-phase">正在读取已保存PDF…</span></div><p class="helper">原文件保留在网站。准备完成后会记录任务编号，随后可关闭窗口。${restartUnconfirmed?'这是重新启动解读，可能产生一次新的模型调用费用。':''}</p>`,{kind:'ai-start-progress'});const revision=modalRevision,report=message=>{const node=$('#ai-start-phase');if(node&&modalRevision===revision)node.textContent=message;};
 try{
  const file=await getPaperBlob(p);let prepared={};if(file){report('正在本地准备原文与图表…');try{prepared=await prepareForAI(p,file,report);}catch{report('本地准备未完成，切换云端准备…');}}
  if(paper(id)?.taskDeletedAt)throw Error('任务已删除，未提交新的AI请求。');report('正在提交后台任务…');let result;
  if(p.cloud)result=await startCloudPaperAnalysis(p.id,prepared.analysisPacket,{restartUnconfirmed});
  else{if(!file)throw Error('未找到原始PDF，请补传原文件。');result=await uploadCloudPaper(file,{title:p.title,tags:p.tags||[],pageCount:p.pages,requestId:p.requestId||uid(),metadata:paperUploadMetadata(p),analysisPacket:prepared.analysisPacket});}
  const stillHere=modalRevision===revision;await mergeCloudDetail(result,{...(!p.cloud?{replaceLocalId:id,file}:{})});scheduleCloudPoll(result.paper.id);if(stillHere&&modalKind==='ai-start-progress')openPaper(result.paper.id);else toast(result.paper.status==='failed'?result.paper.error?.message||'PDF已保留，解读未启动':'后台解读已提交');
 }catch(error){if(modalRevision===revision)modal('文献解读未启动',`<p class="hint">${esc(error.message)}</p><button class="button secondary" data-action="paper" data-id="${esc(id)}">返回原记录</button>`,{kind:'ai-start-error'});else toast(error.message);}finally{startingAnalyses.delete(id);}
}

