try{state=migrateState(undefined);shell();await identifyWorkspace();let imported=false;if(identity.authenticated){db=await openDB('chemlens-user-'+identity.userStorageKey);if(identity.canImportLegacy&&await read('state')===undefined)imported=await importLegacyWorkspace();state=migrateState(await read('state'));}else{db=null;state=migrateState(undefined);}view=locationRoute().view;shell();applyLocationRoute();document.documentElement.dataset.chemlensImportReady='1';if(imported)toast('旧工作区已迁入当前个人账号，原浏览器数据仍保留。');await loadRestoredWorkspace();await loadFigureVisibility();initializeCloud();loadCatalog();void paperTitles.load();if(identity.isCatalogAdmin)loadOwnerReceipts();}catch(err){$('#app').innerHTML=`<div class="empty-state"><h1>暂时无法打开本地工作区</h1><p>浏览器未允许本地数据库，请在正常浏览窗口中打开，并允许网站存储数据。</p><p>${esc(err.message)}</p><button class="button primary" onclick="location.reload()">重新打开</button></div>`;}

async function loadOwnerReceipts(){try{const owned=await cloudOwnerLibrary();ownerUsageEvents=[...new Map([...(state?.backupUsageEvents||[]),...(owned.events||[])].map(e=>[e.id,e])).values()];for(const receipt of owned.papers||[]){const p=seed.papers.find(x=>x.id===receipt.id);if(p)Object.assign(p,receipt);}for(const n of owned.notes||[])if(!seed.notes.some(x=>x.id===n.id))seed.notes.push(n);if(state){const next=restoreCuratedRecords(structuredClone(state),seed);for(const note of owned.notes||[])if(!next.notes.some(x=>x.id===note.id))next.notes.push(note);for(const receipt of owned.papers||[]){const p=next.papers.find(x=>x.id===receipt.id);if(p)Object.assign(p,receipt);}if(identity.authenticated)await commit(next);else render();}}catch{toast('历史用量暂未加载，其他功能可继续使用。');}}

async function submissionRequest(path='',options={}){const response=await fetch('/api/admin/submissions'+path,{credentials:'same-origin',...options,signal:AbortSignal.timeout(60000)}),data=await response.json();if(!response.ok){const e=new Error(data.error?.message||'审核请求未完成');e.status=response.status;throw e;}return data;}
async function loadSubmissions(more=false){if(!identity.isCatalogAdmin||submissionsLoading)return;submissionsLoading=true;try{const data=await submissionRequest(more&&submissionsCursor?'?cursor='+encodeURIComponent(submissionsCursor):'');submissions=more?[...submissions,...data.entries]:data.entries;submissionsCursor=data.nextCursor||'';}catch(e){toast(e.message);}finally{submissionsLoaded=true;submissionsLoading=false;if(view==='admin')renderContent();}}
function submissionPanel(){const rows=submissions.filter(x=>!submissionFilter||x.status===submissionFilter),labels={pending:'待审核',approved:'已准入',rejected:'暂不准入'};return `<section class="panel submission-panel"><div class="section-header"><h2 class="section-title">其他账号上传 · 准入审核</h2><button class="button secondary" data-action="submission-backfill">纳入历史上传审核</button></div><div class="category-tabs">${['pending','approved','rejected',''].map(status=>`<button class="tab ${submissionFilter===status?'active':''}" data-action="submission-filter" data-status="${status}">${labels[status]||'全部'}</button>`).join('')}</div>${submissionsLoading?'<p class="helper">正在读取审核列表…</p>':''}${rows.map(x=>`<article class="submission-row"><div><h3>${esc(x.paper.title)}</h3><p>${esc(x.submitter)} · ${x.paper.pages} 页 · ${esc(({pending:'待解读',queued:'排队解读',processing:'解读中',completed:'已解读',failed:'解读未完成'})[x.paper.status]||'已保存')} · ${labels[x.status]}${x.changedSinceReview?' · 上传者有新修改':''}</p>${x.reason?`<p>${esc(x.reason)}</p>`:''}</div><div class="action-row"><button class="button primary" data-action="submission-review" data-id="${x.id}">预览并审核准入</button>${x.status!=='approved'?`<button class="button secondary" data-action="submission-reject" data-id="${x.id}">暂不准入</button>`:''}</div></article>`).join('')||'<p class="helper">当前没有此状态的文献。</p>'}${submissionsCursor?'<button class="button secondary" data-action="submission-more">加载更多上传</button>':''}</section>`;}
async function prepareSubmissionReview(id){assertCatalogAdmin();if(catalogBusy)return;toast('正在读取这篇投稿的原文和已有解读…');try{const detail=await submissionRequest('/'+id),paper={...detail.paper,id:'member-'+id,cloud:false,example:false,summary:detail.analysis?.summary||'',pdfUrl:detail.pdfUrl};delete paper.resolvedPaperId;const figures=detail.analysis?await analysisFigures(paper,detail.analysis):[],methods=(detail.analysis?.computationalSteps||[]).map((m,i)=>({id:paper.id+':method:'+i,paperId:paper.id,title:m.title,software:m.software,page:m.evidencePage||null,parameters:[m.description,m.parameters].filter(Boolean).join('\n\n'),evidence:m.evidenceText||''})),file=await getPaperBlob(paper);await prepareCatalogReview(paper.id,{paper,figures,methods,file,submission:detail.submission});}catch(e){toast(e.message);}}
async function rejectSubmission(id){const reason=$('[name="submission-reason"]')?.value.trim();if(!reason)return toast('请填写审核说明。');const button=$('[data-action="submission-reject-confirm"]');if(button)button.disabled=true;try{await submissionRequest('/'+id+'/reject',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason})});closeModal();await loadSubmissions();toast('已设为暂不准入，上传者的个人文献保留。');}catch(e){toast(e.message);if(button)button.disabled=false;}}

async function backfillSubmissions(){if(!identity.isCatalogAdmin)return;const button=$('[data-action="submission-backfill"]');if(button)button.disabled=true;try{let cursor='',count=0;do{const d=await submissionRequest('/backfill',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({cursor})});count+=d.indexed;cursor=d.nextCursor||'';if(button?.isConnected)button.textContent='已纳入 '+count+' 篇…';}while(cursor);await loadSubmissions();toast('历史上传检查完成，新纳入 '+count+' 篇待审核文献。');}catch(e){toast(e.message);}finally{if(button?.isConnected){button.disabled=false;button.textContent='纳入历史上传审核';}}}
